    ; Load screen (A = screen ID)
    ; TODO: Implement screen loading logic
    ret

load_screen_new_playable_screen_777564659476:
    ; Load New Playable Screen screen (fast direct port access)
    ld a, 0
    ld (current_screen_engine), a
    ld a, #FF
    ld (autocontrol_screen_id), a
    ; Set VDP colors FIRST (before loading screen data)
    ld a, 1           ; Background color
    ld b, 1       ; Border color
    call set_screen_colors
    ; Initialize character 0 (empty cells) with background color
    ld a, 1           ; Background color for char 0
    call init_char0_color
    ld a, (current_screen2_tilebank_id)
    cp SCREEN2_TILEBANK_TILEBANK_1777551611737_ID
    jr z, .load_new_playable_screen_777564659476_tilebank_ready
    call load_tilebank_tilebank_1777551611737_patterns_to_vram
    call load_tilebank_tilebank_1777551611737_colors_to_vram
    ld a, SCREEN2_TILEBANK_TILEBANK_1777551611737_ID
    ld (current_screen2_tilebank_id), a
    xor a
    ld (vram_cache_font_ready), a
    call init_font_system
.load_new_playable_screen_777564659476_tilebank_ready:
    ; Build mutable runtime screen background maps in RAM
    ; Decompress ZX0 screen layout into RAM buffer
    di
    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_LAYOUT
    ld de, ZX0_SCREEN_BUFFER
    call dzx0_standard
    ei
    ld hl, ZX0_SCREEN_BUFFER
    ld de, runtime_background_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    ld hl, ZX0_SCREEN_BUFFER
    ld de, runtime_screen_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    ; Decompress ZX0 effects layout directly into runtime_effects_layout
    di
    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_EFFECTS_LAYOUT
    ld de, runtime_effects_layout
    call dzx0_standard
    ei
    ld hl, runtime_effects_layout
    ld de, runtime_effects_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ; Decompress ZX0 behavior map into RAM buffer
    di
    ld hl, BEHAVIOR_NEW_PLAYABLE_SCREEN_0_DATA
    ld de, ZX0_BEHAVIOR_BUFFER
    call dzx0_standard
    ei
    ld hl, ZX0_BEHAVIOR_BUFFER
    ld de, runtime_behavior_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_INTERACTION_TYPE_MAP
    ld de, runtime_interaction_type_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_INTERACTION_VALUE_MAP
    ld de, runtime_interaction_value_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_INTERACTION_TARGET_MAP
    ld de, runtime_interaction_target_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld a, 0
    ld (current_effect_zone_count), a
    or a
    jr z, .load_new_playable_screen_777564659476_zones_done
    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_EFFECT_ZONE_TABLE
    ld de, runtime_effect_zone_table
    ld bc, 0
    ldir
.load_new_playable_screen_777564659476_zones_done:
    ; Now load screen layout (full 32x24) from runtime RAM buffer
    ld hl, runtime_screen_layout
    ld de, NAMETBL
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    call FAST_LDIRVM           ; Fast VRAM write (direct port access)
    ld a, 0
    ld (current_screen_anim_group_count), a
    ld a, 0
    ld (current_screen_entity_count), a
    ld a, 1
    ld (current_screen_sprite_pattern_slots), a
    ld a, SCREEN_NEW_PLAYABLE_SCREEN_0_SUMMARY_FLAGS
    ld (current_screen_summary_flags), a
    ld a, SCREEN_NEW_PLAYABLE_SCREEN_0_BOSS_COUNT
    ld (current_screen_boss_count), a
    or a
    jp z, load_new_playable_screen_777564659476_boss_done
    ld hl, SCREEN_NEW_PLAYABLE_SCREEN_0_BOSS_TABLE
    ld de, current_screen_boss_entry
    ld bc, BOSS_PLACEMENT_ENTRY_SIZE
    ldir
    ld hl, current_screen_boss_entry
    ld (current_screen_boss_table), hl
    ld a, #FF
    ld (current_screen_boss_table_bank), a
load_new_playable_screen_777564659476_boss_done:

    call init_screen_boss_from_current_screen
    ; Initialize collision system pointers for this screen
    ld hl, runtime_screen_layout
    ld (current_screen_layout), hl
    ld a, #FF
    ld (current_screen_layout_bank), a
    ld hl, runtime_behavior_map
    ld (current_behavior_map), hl
    ld a, #FF
    ld (current_behavior_map_bank), a
    ld a, l
    ld (behavior_cache_map_l), a
    ld a, h
    ld (behavior_cache_map_h), a
    ld a, #FF
    ld (behavior_cache_row), a
    xor a
    ld (secret_zone_active), a
    ld (secret_zone_rect_x), a
    ld (secret_zone_rect_y), a
    ld (secret_zone_rect_w), a
    ld (secret_zone_rect_h), a
    ld hl, entity_button_contact_active
    ld de, entity_button_contact_active + 1
    ld bc, 31
    ld (hl), a
    ldir
    ret


