; ==================================================================
; PSG SOUND SYSTEM
; File: sound.asm
; Description: AY-3-8910 PSG control and sound effects
; Engine Audio Tick: GameFlow/game loop
; ==================================================================

; ==================================================================
; PSG REGISTER ADDRESSES
; ==================================================================

; Tone Generators (Channels A, B, C)
PSG_TONE_A_LO       EQU 0        ; Channel A period low byte
PSG_TONE_A_HI       EQU 1        ; Channel A period high byte (4 bits)
PSG_TONE_B_LO       EQU 2        ; Channel B period low byte
PSG_TONE_B_HI       EQU 3        ; Channel B period high byte (4 bits)
PSG_TONE_C_LO       EQU 4        ; Channel C period low byte
PSG_TONE_C_HI       EQU 5        ; Channel C period high byte (4 bits)

; Noise Generator
PSG_NOISE_PERIOD    EQU 6        ; Noise period (5 bits)

; Mixer Control
PSG_MIXER           EQU 7        ; Mixer/Enable register
; Bit 0: Channel A tone enable (0=on, 1=off)
; Bit 1: Channel B tone enable
; Bit 2: Channel C tone enable
; Bit 3: Channel A noise enable (0=on, 1=off)
; Bit 4: Channel B noise enable
; Bit 5: Channel C noise enable

; Volume Control
PSG_VOL_A           EQU 8        ; Channel A volume (4 bits) + envelope flag (bit 4)
PSG_VOL_B           EQU 9        ; Channel B volume
PSG_VOL_C           EQU 10       ; Channel C volume

; Envelope Generator
PSG_ENV_LO          EQU 11       ; Envelope period low byte
PSG_ENV_HI          EQU 12       ; Envelope period high byte
PSG_ENV_SHAPE       EQU 13       ; Envelope shape (4 bits)

; ==================================================================
; PSG TONE PERIODS (Musical notes, octave 4, 3.579545 MHz clock)
; ==================================================================

; Note frequencies for octave 4 (middle C = C4)
NOTE_C4         EQU 477      ; C  - 261.63 Hz
NOTE_CS4        EQU 450      ; C# - 277.18 Hz
NOTE_D4         EQU 425      ; D  - 293.66 Hz
NOTE_DS4        EQU 401      ; D# - 311.13 Hz
NOTE_E4         EQU 379      ; E  - 329.63 Hz
NOTE_F4         EQU 357      ; F  - 349.23 Hz
NOTE_FS4        EQU 337      ; F# - 369.99 Hz
NOTE_G4         EQU 318      ; G  - 392.00 Hz
NOTE_GS4        EQU 300      ; G# - 415.30 Hz
NOTE_A4         EQU 284      ; A  - 440.00 Hz
NOTE_AS4        EQU 268      ; A# - 466.16 Hz
NOTE_B4         EQU 253      ; B  - 493.88 Hz
NOTE_C5         EQU 238      ; C5 - 523.25 Hz

; Octave multipliers: Divide period by 2 for +1 octave, multiply by 2 for -1 octave

; ==================================================================
; SOUND EFFECT DURATIONS (in frames, 60Hz)
; ==================================================================

SFX_SHORT           EQU 5        ; ~83ms
SFX_MEDIUM          EQU 15       ; ~250ms
SFX_LONG            EQU 30       ; ~500ms

; ==================================================================
; SOUND SYSTEM INITIALIZATION
; ==================================================================

init_sound_system:
    ; Initialize PSG via BIOS
    call GICINI

    ; Clear runtime sound state so power-on RAM garbage cannot make
    ; sfx_update / SM_UpdateSound drive the PSG for a few random frames.
    xor a
    ld (sfx_active), a
    ld (sfx_timer), a
    ld (sfx_fadeout), a
    ld (sm_sound_active), a
    ld (sm_sound_frames_left), a
    ld (sm_sound_ptr_l), a
    ld (sm_sound_ptr_h), a
    call music_init_system

    ; Silence all channels
    call sfx_silence_all

    ret

; ------------------------------------------------------------------
; task_audio_tick
; Shared audio tick wrapper for IRQ task_manager or HALT game loops.
; Preserves caller-visible registers on every exit path.
; ------------------------------------------------------------------
task_audio_tick:
    push af
    push bc
    push de
    push hl

    call music_update


    pop hl
    pop de
    pop bc
    pop af
    ret

; ==================================================================
; PSG LOW-LEVEL CONTROL FUNCTIONS
; ==================================================================

; ------------------------------------------------------------------
; psg_write
; Write to PSG register via BIOS
; Input:  A = Register number (0-13)
;         E = Value to write
; Destroys: AF, E
; ------------------------------------------------------------------
psg_write:
    call WRTPSG
    ret

; ------------------------------------------------------------------
; psg_set_tone
; Set tone period for a channel
; Input:  A = Channel (0=A, 1=B, 2=C)
;         HL = Tone period (clamped to PSG 12-bit range 1..#0FFF)
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
psg_set_tone:
    ld b, a                      ; Preserve channel while clamping period
    ld a, h
    and #F0
    jr z, .tone_period_in_range
    ld hl, #0FFF                 ; AY tone period is 12-bit; saturate overflow
.tone_period_in_range:
    ld a, h
    or l
    jr nz, .tone_period_nonzero
    inc l                        ; Avoid period 0, which is unstable on PSG
.tone_period_nonzero:
    ld a, b
    ; Calculate register numbers (A*2 for low, A*2+1 for high)
    add a, a                     ; A = channel * 2
    ld c, a                      ; C = low register number
    inc a
    ld b, a                      ; B = high register number

    ; Write low byte
    ld a, c
    ld e, l
    call WRTPSG

    ; Write high byte (only lower 4 bits)
    ld a, b
    ld e, h
    ld a, e
    and #0F
    ld e, a
    ld a, b
    call WRTPSG

    ret

; ------------------------------------------------------------------
; psg_set_volume
; Set volume for a channel
; Input:  A = Channel (0=A, 1=B, 2=C)
;         B = Volume (0-15) or #10 to enable PSG hardware envelope
; Destroys: AF, E
; ------------------------------------------------------------------
psg_set_volume:
    add a, PSG_VOL_A             ; A = PSG_VOL_x register
    ld e, b                      ; E = volume value
    call WRTPSG
    ret

; ------------------------------------------------------------------
; psg_set_noise
; Set noise generator period
; Input:  A = Noise period (0-31)
; Destroys: AF, E
; ------------------------------------------------------------------
psg_set_noise:
    ld e, a
    ld a, PSG_NOISE_PERIOD
    call WRTPSG
    ret

; ------------------------------------------------------------------
; psg_set_mixer
; Set mixer control (enable/disable tone and noise)
; Input:  A = Mixer value
;         Bits 0-2: Tone off (0=on, 1=off) for channels A,B,C
;         Bits 3-5: Noise off (0=on, 1=off) for channels A,B,C
; Destroys: AF, E
; ------------------------------------------------------------------
psg_set_mixer:
    ld e, a
    ld a, PSG_MIXER
    call WRTPSG
    ret

; ------------------------------------------------------------------
; psg_set_envelope
; Program the global PSG hardware envelope generator
; Input:  HL = Envelope period
;         B = Envelope shape (0-15)
; Destroys: AF, E
; ------------------------------------------------------------------
psg_set_envelope:
    ld a, PSG_ENV_LO
    ld e, l
    call WRTPSG
    ld a, PSG_ENV_HI
    ld e, h
    call WRTPSG
    ld a, b
    and #0F
    ld e, a
    ld a, PSG_ENV_SHAPE
    call WRTPSG
    ret

; ==================================================================
; HIGH-LEVEL SOUND EFFECTS
; ==================================================================

; ------------------------------------------------------------------
; sfx_silence_all
; Silence all PSG channels
; ------------------------------------------------------------------
sfx_silence_all:
    ; Set all volumes to 0
    xor a                        ; A = channel A
    ld b, 0                      ; B = volume 0
    call psg_set_volume

    ld a, 1                      ; A = channel B
    ld b, 0
    call psg_set_volume

    ld a, 2                      ; A = channel C
    ld b, 0
    call psg_set_volume

    ; Disable all tone and noise
    ld a, #3F                    ; All tone and noise off
    call psg_set_mixer

    ret

; ------------------------------------------------------------------
; sfx_beep
; Simple beep sound
; ------------------------------------------------------------------
sfx_beep:
    ; Channel A: 440Hz (A4)
    xor a                        ; A = channel A
    ld hl, NOTE_A4
    call psg_set_tone

    ; Volume 12
    xor a
    ld b, 12
    call psg_set_volume

    ; Enable tone A only
    ld a, #3E                    ; Tone A on, others off
    call psg_set_mixer

    ret

; ------------------------------------------------------------------
; sfx_jump
; Jump sound effect (rising pitch)
; ------------------------------------------------------------------
sfx_jump:
    ; Channel A: Start at C4, quick rise
    xor a
    ld hl, NOTE_C4
    call psg_set_tone

    ; Volume 10
    xor a
    ld b, 10
    call psg_set_volume

    ; Enable tone A
    ld a, #3E
    call psg_set_mixer

    ; TODO: Add pitch sweep for realistic jump sound
    ret

; ------------------------------------------------------------------
; sfx_shoot
; Shooting sound (noise + low tone)
; ------------------------------------------------------------------
sfx_shoot:
    ; Channel A: Low tone
    xor a
    ld hl, 100                   ; Low period = high pitch
    call psg_set_tone

    ; Volume 8
    xor a
    ld b, 8
    call psg_set_volume

    ; Noise generator at period 5
    ld a, 5
    call psg_set_noise

    ; Enable tone A + noise A
    ld a, #36                    ; Tone A + Noise A on
    call psg_set_mixer

    ret

; ------------------------------------------------------------------
; sfx_explosion
; Explosion sound (noise-heavy)
; ------------------------------------------------------------------
sfx_explosion:
    ; Noise generator at period 10
    ld a, 10
    call psg_set_noise

    ; Channel A: Volume 15 (max) with noise
    xor a
    ld b, 15
    call psg_set_volume

    ; Enable noise A only (no tone)
    ld a, #39                    ; Noise A on, tone off
    call psg_set_mixer

    ret

; ------------------------------------------------------------------
; sfx_coin
; Coin/pickup sound (quick ascending notes)
; ------------------------------------------------------------------
sfx_coin:
    ; Channel B: E4 note
    ld a, 1                      ; Channel B
    ld hl, NOTE_E4
    call psg_set_tone

    ; Volume 10
    ld a, 1
    ld b, 10
    call psg_set_volume

    ; Enable tone B
    ld a, #3D                    ; Tone B on, others off
    call psg_set_mixer

    ; TODO: Quick ascend to G4 for classic coin sound
    ret

; ------------------------------------------------------------------
; sfx_damage
; Damage/hit sound (harsh noise)
; ------------------------------------------------------------------
sfx_damage:
    ; Short noise burst
    ld a, 3                      ; Harsh noise period
    call psg_set_noise

    ; Channel C: Volume 12
    ld a, 2                      ; Channel C
    ld b, 12
    call psg_set_volume

    ; Enable noise C only
    ld a, #1F                    ; Noise C on
    call psg_set_mixer

    ret

; ==================================================================
; SOUND EFFECT PLAYBACK SYSTEM
; ==================================================================
; This section provides a simple sound effect manager that can
; play effects with automatic duration and fadeout

; Runtime state lives in variables.asm:
;   sfx_active, sfx_timer, sfx_fadeout

; ------------------------------------------------------------------
; play_sound_effect
; Play one of the built-in sound effects by ID
; Input:  A = sound ID
;         0=beep, 1=jump, 2=shoot, 3=explosion, 4=coin, 5=damage
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
play_sound_effect:
    ld b, a
    ld a, (music_active)
    or a
    ret nz
    ld a, b
    cp 1
    jp z, play_sound_effect_jump
    cp 2
    jp z, play_sound_effect_shoot
    cp 3
    jp z, play_sound_effect_explosion
    cp 4
    jp z, play_sound_effect_coin
    cp 5
    jp z, play_sound_effect_damage

play_sound_effect_beep:
    ld hl, sfx_beep
    ld b, SFX_SHORT
    call sfx_play
    ret

play_sound_effect_jump:
    ld hl, sfx_jump
    ld b, SFX_SHORT
    call sfx_play
    ret

play_sound_effect_shoot:
    ld hl, sfx_shoot
    ld b, SFX_SHORT
    call sfx_play
    ret

play_sound_effect_explosion:
    ld hl, sfx_explosion
    ld b, SFX_MEDIUM
    call sfx_play
    ret

play_sound_effect_coin:
    ld hl, sfx_coin
    ld b, SFX_SHORT
    call sfx_play
    ret

play_sound_effect_damage:
    ld hl, sfx_damage
    ld b, SFX_SHORT
    call sfx_play
    ret

; ------------------------------------------------------------------
; sfx_play
; Play a sound effect with duration
; Input:  HL = Sound effect function address
;         B = Duration in frames
; ------------------------------------------------------------------
sfx_play:
    ld a, (music_active)
    or a
    ret nz
    ; Call the sound effect function
    push bc
    push hl
    ld de, .return_address
    push de
    jp (hl)                      ; Indirect call
.return_address:
    pop hl
    pop bc

    ; Set timer
    ld a, b
    ld (sfx_timer), a

    ; Mark as active
    ld a, 1
    ld (sfx_active), a

    ret

; ------------------------------------------------------------------
; sfx_update
; Update sound effect system (call every frame)
; Handles automatic fadeout and silence
; ------------------------------------------------------------------
sfx_update:
    ld a, (music_active)
    or a
    ret nz
    ; Check if sound is active
    ld a, (sfx_active)
    or a
    ret z                        ; No active sound

    ; Decrement timer
    ld a, (sfx_timer)
    or a
    jr z, .silence_now

    dec a
    ld (sfx_timer), a

    ; Check if entering fadeout zone (last 5 frames)
    cp 5
    ret nc                       ; Still in main sound

    ; TODO: Implement volume fadeout here
    ret

.silence_now:
    call sfx_silence_all
    xor a
    ld (sfx_active), a
    ret

; ==================================================================
; TRACKER MUSIC RUNTIME (Phase 1)
; Phase 1 plays row data and loop state in ROM; descriptor tables are
; serialized now for compatibility and future expansion.
; ==================================================================

MUSIC_TRACK_ORDER_TABLE     EQU 5
MUSIC_TRACK_PATTERN_TABLE   EQU 7
MUSIC_TRACK_INSTRUMENT_TABLE EQU 9
MUSIC_TRACK_ORNAMENT_TABLE  EQU 11
MUSIC_TRACK_NOISE_DEFAULT   EQU 15

; ------------------------------------------------------------------
; music_init_system
; Reset tracker runtime RAM and default PSG mixer shadow.
; Input:  None
; Output: music_active=0, music_muted=0, music_mixer_shadow=#3F
; Destroys: AF
; ------------------------------------------------------------------
music_init_system:
    xor a
    ld (music_active), a
    ld (music_muted), a
    ld (music_loop), a
    ld (music_track_index), a
    ld (music_row_frames), a
    ld (music_row_countdown), a
    ld (music_order_pos), a
    ld (music_pattern_index), a
    ld (music_pattern_row), a
    ld (music_pattern_rows), a
    ld (music_track_ptr_l), a
    ld (music_track_ptr_h), a
    ld (music_pattern_ptr_l), a
    ld (music_pattern_ptr_h), a
    ld a, #3F
    ld (music_mixer_shadow), a
    call music_reset_channel_state
    ret

music_reset_channel_state:
    ld a, #FF
    ld (music_ch_a_note), a
    ld (music_ch_b_note), a
    ld (music_ch_c_note), a
    xor a
    ld (music_ch_a_instrument), a
    ld (music_ch_b_instrument), a
    ld (music_ch_c_instrument), a
    ld (music_ch_a_ornament), a
    ld (music_ch_b_ornament), a
    ld (music_ch_c_ornament), a
    ld (music_ch_a_vol_step), a
    ld (music_ch_b_vol_step), a
    ld (music_ch_c_vol_step), a
    ld (music_ch_a_tone_step), a
    ld (music_ch_b_tone_step), a
    ld (music_ch_c_tone_step), a
    ld (music_ch_a_noise_step), a
    ld (music_ch_b_noise_step), a
    ld (music_ch_c_noise_step), a
    ld (music_ch_a_orn_step), a
    ld (music_ch_b_orn_step), a
    ld (music_ch_c_orn_step), a
    ld (music_ch_a_hw_env_step), a
    ld (music_ch_b_hw_env_step), a
    ld (music_ch_c_hw_env_step), a
    ld a, #0F
    ld (music_ch_a_volume), a
    ld (music_ch_b_volume), a
    ld (music_ch_c_volume), a
    ret

music_silence_channels:
    xor a
    ld b, 0
    call psg_set_volume
    ld a, 1
    ld b, 0
    call psg_set_volume
    ld a, 2
    ld b, 0
    call psg_set_volume
    ld a, #3F
    call psg_set_mixer
    ret

music_stop:
    push af
    call music_init_system
    call music_silence_channels
    pop af
    ret

music_mute:
    ld a, (music_active)
    or a
    ret z
    ld a, 1
    ld (music_muted), a
    call music_silence_channels
    ret

music_resume:
    ld a, (music_active)
    or a
    ret z
    xor a
    ld (music_muted), a
    call music_update_channel_effects
    ret

; ------------------------------------------------------------------
; music_execute_command
; Dispatch a compact music command stream used by Game Flow nodes.
; Input:  DE -> [command, trackIndex, loopFlag]
;         command: 0=stop, 1=play, 2=mute, 3=resume, #FF=no-op
; Output: Selected command executed, DE may advance while parsing
; Destroys: AF, BC (play path), DE (play path), HL (via callees)
; ------------------------------------------------------------------
music_execute_command:
    ld a, (de)
    cp #FF
    ret z
    or a
    jp z, music_stop
    cp 1
    jp z, .play_track
    cp 2
    jp z, music_mute
    cp 3
    jp z, music_resume
    ret
.play_track:
    inc de
    ld a, (de)
    ld c, a
    inc de
    ld a, (de)
    ld b, a
    ld a, c
    call music_play_track
    ret

music_load_track_pointer_from_index:
    add a, a
    ld e, a
    ld d, 0
    ld hl, music_track_ptr_table
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld a, e
    ld (music_track_ptr_l), a
    ld a, d
    ld (music_track_ptr_h), a
    or a
    ret

music_get_track_ptr:
    ld a, (music_track_ptr_l)
    ld l, a
    ld a, (music_track_ptr_h)
    ld h, a
    ret

music_get_track_header_ptr:
    ld e, a
    ld d, 0
    call music_get_track_ptr
    add hl, de
    ret

music_read_track_byte:
    call music_get_track_header_ptr
    ld a, (hl)
    ret

music_read_track_word:
    call music_get_track_header_ptr
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ret

music_get_instrument_ptr:
    or a
    jr z, .no_instrument
    add a, a
    ld e, a
    ld d, 0
    push de
    ld a, MUSIC_TRACK_INSTRUMENT_TABLE
    call music_read_track_word
    pop de
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ret
.no_instrument:
    ld hl, 0
    ret

; ------------------------------------------------------------------
; music_get_channel_instrument_ptr
; Resolve current channel instrument pointer from the cached channel id.
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: HL = instrument descriptor or 0 when none is active
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
music_get_channel_instrument_ptr:
    ld hl, music_ch_instrument_base
    call music_load_channel_byte
    call music_get_instrument_ptr
    ret

; ------------------------------------------------------------------
; music_get_channel_ornament_ptr
; Resolve current channel ornament pointer from the cached ornament id.
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: HL = ornament descriptor or 0 when none is active
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
music_get_channel_ornament_ptr:
    ld hl, music_ch_ornament_base
    call music_load_channel_byte
    or a
    jr z, .no_ornament
    add a, a
    ld e, a
    ld d, 0
    push de
    ld a, MUSIC_TRACK_ORNAMENT_TABLE
    call music_read_track_word
    pop de
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ret
.no_ornament:
    ld hl, 0
    ret

; ------------------------------------------------------------------
; music_apply_signed_offset_to_note_work
; Apply signed semitone offset in A to music_pitch_note_work, clamped 0..95.
; ------------------------------------------------------------------
music_apply_signed_offset_to_note_work:
    bit 7, a
    jr z, .positive_offset
    cpl
    inc a
    ld e, a
    ld a, (music_pitch_note_work)
    cp e
    jr nc, .subtract_ok
    xor a
    ld (music_pitch_note_work), a
    ret
.subtract_ok:
    sub e
    ld (music_pitch_note_work), a
    ret
.positive_offset:
    ld e, a
    ld a, (music_pitch_note_work)
    add a, e
    jr c, .clamp_high
    cp 96
    jr c, .store_positive
.clamp_high:
    ld a, 95
.store_positive:
    ld (music_pitch_note_work), a
    ret

; ------------------------------------------------------------------
; music_apply_channel_tone_macro
; Apply active instrument toneEnvelope as relative semitone offsets.
; Input:  C = channel index, B = current note index
; Output: B = adjusted note index
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
music_apply_channel_tone_macro:
    ld a, b
    ld (music_pitch_note_work), a
    call music_get_channel_instrument_ptr
    ld a, h
    or l
    jp z, .tone_done
    push hl
    ld de, 12
    add hl, de
    ld a, (hl)
    pop hl
    or a
    jp z, .tone_done
    ld (music_pitch_len_work), a
    push hl
    ld hl, music_ch_tone_step_base
    call music_load_channel_byte
    pop hl
    ld e, a
    ld d, e
    ld a, (music_pitch_len_work)
    cp d
    jr z, .tone_step_clamp
    jr nc, .tone_step_in_range
.tone_step_clamp:
    dec a
    ld e, a
.tone_step_in_range:
    ld a, e
    ld (music_pitch_step_work), a
    inc a
    ld e, a
    ld d, e
    ld a, (music_pitch_len_work)
    cp d
    jr z, .tone_use_loop
    jr nc, .tone_store_next
.tone_use_loop:
    push hl
    ld de, 13
    add hl, de
    ld e, (hl)
    pop hl
    ld d, e
    ld a, (music_pitch_len_work)
    cp d
    jr z, .tone_loop_clamp
    jr nc, .tone_store_next
.tone_loop_clamp:
    dec a
    ld e, a
.tone_store_next:
    ld a, e
    push hl
    ld hl, music_ch_tone_step_base
    call music_store_channel_byte
    pop hl
    push hl
    ld de, 10
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ld a, (music_pitch_step_work)
    ld e, a
    ld d, 0
    add hl, de
    ld a, (hl)
    call music_apply_signed_offset_to_note_work
    pop hl
.tone_done:
    ld a, (music_pitch_note_work)
    ld b, a
    ret

; ------------------------------------------------------------------
; music_apply_channel_ornament_macro
; Apply active ornament as relative semitone offsets without pitch drift.
; Input:  C = channel index, B = current note index
; Output: B = adjusted note index
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
music_apply_channel_ornament_macro:
    ld a, b
    ld (music_pitch_note_work), a
    call music_get_channel_ornament_ptr
    ld a, h
    or l
    jp z, .orn_done
    push hl
    inc hl
    inc hl
    ld a, (hl)
    pop hl
    or a
    jp z, .orn_done
    ld (music_pitch_len_work), a
    push hl
    ld hl, music_ch_orn_step_base
    call music_load_channel_byte
    pop hl
    ld e, a
    ld d, e
    ld a, (music_pitch_len_work)
    cp d
    jr z, .orn_step_clamp
    jr nc, .orn_step_in_range
.orn_step_clamp:
    dec a
    ld e, a
.orn_step_in_range:
    ld a, e
    ld (music_pitch_step_work), a
    inc a
    ld e, a
    ld d, e
    ld a, (music_pitch_len_work)
    cp d
    jr z, .orn_use_loop
    jr nc, .orn_store_next
.orn_use_loop:
    push hl
    ld de, 3
    add hl, de
    ld e, (hl)
    pop hl
    ld d, e
    ld a, (music_pitch_len_work)
    cp d
    jr z, .orn_loop_clamp
    jr nc, .orn_store_next
.orn_loop_clamp:
    dec a
    ld e, a
.orn_store_next:
    ld a, e
    push hl
    ld hl, music_ch_orn_step_base
    call music_store_channel_byte
    pop hl
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ld a, (music_pitch_step_work)
    ld e, a
    ld d, 0
    add hl, de
    ld a, (hl)
    call music_apply_signed_offset_to_note_work
.orn_done:
    ld a, (music_pitch_note_work)
    ld b, a
    ret

; ------------------------------------------------------------------
; music_resolve_channel_note_index
; Combine base note + tone macro + ornament into final note index.
; Input:  C = channel index
; Output: A = final note index or #FF when silent
; Destroys: AF, B, DE, HL
; ------------------------------------------------------------------
music_resolve_channel_note_index:
    ld hl, music_ch_note_base
    call music_load_channel_byte
    cp #FF
    ret z
    ld b, a
    call music_apply_channel_tone_macro
    call music_apply_channel_ornament_macro
    ld a, b
    ret

; ------------------------------------------------------------------
; music_channel_uses_hardware_env
; Check if the active instrument routes channel volume through PSG ENV.
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: A = 1 when PSG hardware envelope is enabled, else 0
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
music_channel_uses_hardware_env:
    push hl
    call music_get_channel_instrument_ptr
    ld a, h
    or l
    jr z, music_channel_uses_hardware_env_no_hw_env
    ld a, (hl)
    and #04
    jr z, music_channel_uses_hardware_env_no_hw_env
    ld a, 1
    pop hl
    ret
music_channel_uses_hardware_env_no_hw_env:
    xor a
    pop hl
    ret

; ------------------------------------------------------------------
; music_trigger_channel_attack
; Hook kept for compatibility. The preview-style hardware envelope is
; emulated in software per channel, so new-note state is already reset
; by music_apply_channel_cell before this helper is called.
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: None
; Destroys: None
; ------------------------------------------------------------------
music_trigger_channel_attack:
    ret

; ------------------------------------------------------------------
; music_resolve_channel_volume
; Resolve per-frame channel volume.
; Current Phase 1 behavior:
; - emulates AY hardware envelope shapes in software when ayEnvelopeShape is set
; - falls back to music_ch_volume_base when no envelope data exists
; - applies a simple software volumeEnvelope when present
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: B = PSG volume 0-15
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
music_resolve_channel_volume:
    push af
    push de
    push hl
    ld hl, music_ch_instrument_base
    call music_load_channel_byte
    or a
    jp z, .fallback_base
    call music_get_instrument_ptr
    ld a, h
    or l
    jp z, .fallback_base
    ld a, (hl)
    and #04
    jp nz, .hardware_env
.check_software_env:
    push hl
    ld de, 8
    add hl, de
    ld b, (hl)
    pop hl
    ld a, b
    or a
    jp z, .fallback_base
    push hl
    ld de, 6
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    pop hl
    push hl
    ld hl, music_ch_vol_step_base
    call music_load_channel_byte
    cp b
    jr c, .step_ok_restore
    pop hl
    push de
    push hl
    ld de, 9
    add hl, de
    ld a, (hl)
    pop hl
    pop de
    cp b
    jr c, .step_ok
    ld a, b
    push af
    ld hl, music_ch_vol_step_base
    call music_store_channel_byte
    pop af
    ld hl, music_ch_note_base
    ld a, #FF
    call music_store_channel_byte
    xor a
    ld b, a
    jp .mrcv_done
.step_ok_restore:
    pop hl
.step_ok:
    push af
    inc a
    cp b
    jr c, .next_step_ok
    push de
    push hl
    ld de, 9
    add hl, de
    ld a, (hl)
    pop hl
    pop de
    cp b
    jr c, .next_step_ok
    ld a, b
.next_step_ok:
    push de
    ld hl, music_ch_vol_step_base
    call music_store_channel_byte
    pop de
    pop af
    ld l, a
    ld h, 0
    add hl, de
    ld a, (hl)
    cp 16
    jr c, .env_volume_ok
    ld a, 15
.env_volume_ok:
    ld b, a
    jp .mrcv_done
.hardware_env:
    ld hl, music_ch_hw_env_step_base
    call music_load_channel_byte
    inc a
    cp 2
    jr c, .hw_store_counter
    xor a
    push af
    ld hl, music_ch_hw_env_step_base
    call music_store_channel_byte
    pop af
    ld hl, music_ch_vol_step_base
    call music_load_channel_byte
    cp 15
    jr nc, .hw_phase_ready
    inc a
    push af
    ld hl, music_ch_vol_step_base
    call music_store_channel_byte
    pop af
    jr .hw_phase_ready
.hw_store_counter:
    push af
    ld hl, music_ch_hw_env_step_base
    call music_store_channel_byte
    pop af
    ld hl, music_ch_vol_step_base
    call music_load_channel_byte
.hw_phase_ready:
    push af
    call music_get_channel_instrument_ptr
    ld a, h
    or l
    pop af
    jr z, .hw_decay
    push af
    inc hl
    inc hl
    ld a, (hl)
    and #04
    pop af
    jr z, .hw_decay
    ld b, a
    jp .mrcv_done
.hw_decay:
    ld e, a
    ld a, 15
    sub e
    ld b, a
    jp .mrcv_done
.fallback_base:
    ld hl, music_ch_volume_base
    call music_load_channel_byte
    ld b, a
.mrcv_done:
    pop hl
    pop de
    pop af
    ret

; ------------------------------------------------------------------
; music_resolve_channel_noise
; Resolve per-frame channel noise period, including the PT3-inspired
; software noise macro appended to the instrument descriptor.
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: A = PSG noise period 0-31
; Destroys: AF, DE, HL
; Preserves: Stack balance restored before return
; ------------------------------------------------------------------
music_resolve_channel_noise:
    push de
    push hl
    ld hl, music_ch_instrument_base
    call music_load_channel_byte
    or a
    jp z, .mrcn_track_default
    call music_get_instrument_ptr
    ld a, h
    or l
    jp z, .mrcn_track_default
    push hl
    ld de, 16
    add hl, de
    ld b, (hl)
    pop hl
    ld a, b
    or a
    jp z, .mrcn_static_noise
    push hl
    ld hl, music_ch_noise_step_base
    call music_load_channel_byte
    cp b
    jr c, .mrcn_step_ok
    ld a, b
    dec a
.mrcn_step_ok:
    push af
    pop af
    pop hl
    push af
    inc a
    cp b
    jr c, .mrcn_store_next
    push de
    ld de, 17
    add hl, de
    ld a, (hl)
    pop de
    cp b
    jr c, .mrcn_store_next
    ld a, b
    dec a
.mrcn_store_next:
    push hl
    push af
    ld hl, music_ch_noise_step_base
    call music_store_channel_byte
    pop af
    pop hl
    ld de, 14
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    pop af
    ld l, a
    ld h, 0
    add hl, de
    ld a, (hl)
    and #1F
    jp .mrcn_done
.mrcn_static_noise:
    push de
    ld de, 3
    add hl, de
    ld a, (hl)
    pop de
    and #1F
    jp .mrcn_done
.mrcn_track_default:
    ld a, MUSIC_TRACK_NOISE_DEFAULT
    call music_read_track_byte
    and #1F
.mrcn_done:
    pop hl
    pop de
    ret

; ------------------------------------------------------------------
; music_play_track
; Start a serialized PSG tracker song from ROM.
; Input:  A = track index in music_track_ptr_table
;         B bit 0 = loop enabled flag
; Output: music_active=1 and first row applied immediately
; Destroys: AF, BC, DE, HL
; Preserves: Stack balance restored on all exits
; ------------------------------------------------------------------
music_play_track:
    push bc
    push de
    push hl
    ld hl, music_track_count
    cp (hl)
    jp nc, .mpt_done
    ld (music_track_index), a
    call music_load_track_pointer_from_index
    jp c, .mpt_done
    ld a, b
    and 1
    ld (music_loop), a
    xor a
    ld (music_muted), a
    ld (music_order_pos), a
    ld (music_pattern_index), a
    ld (music_pattern_row), a
    ld a, 1
    ld (music_active), a
    call music_reset_channel_state
    call music_apply_row
.mpt_done:
    pop hl
    pop de
    pop bc
    ret

music_store_channel_byte:
    push de
    ld e, c
    ld d, 0
    add hl, de
    ld (hl), a
    pop de
    ret

music_load_channel_byte:
    push de
    ld e, c
    ld d, 0
    add hl, de
    ld a, (hl)
    pop de
    ret

music_apply_channel_cell:
    ld c, a
    ld d, 0
    ld a, (hl)
    inc hl
    cp #FF
    jp z, .note_done
    cp #FE
    jp nz, .store_note
    ld a, #FF
    jr .store_note
.store_note:
    cp #FF
    jr z, .store_note_value
    ld d, 1
.store_note_value:
    push hl
    ld hl, music_ch_note_base
    call music_store_channel_byte
    xor a
    ld hl, music_ch_vol_step_base
    call music_store_channel_byte
    ld hl, music_ch_tone_step_base
    call music_store_channel_byte
    ld hl, music_ch_noise_step_base
    call music_store_channel_byte
    ld hl, music_ch_orn_step_base
    call music_store_channel_byte
    ld hl, music_ch_hw_env_step_base
    call music_store_channel_byte
    pop hl
.note_done:
    ld a, (hl)
    inc hl
    cp #FF
    jp z, .instrument_done
    push hl
    ld hl, music_ch_instrument_base
    call music_store_channel_byte
    pop hl
.instrument_done:
    ld a, (hl)
    inc hl
    cp #FF
    jp z, .ornament_done
    push hl
    ld hl, music_ch_ornament_base
    call music_store_channel_byte
    pop hl
.ornament_done:
    ld a, (hl)
    inc hl
    cp #FF
    jr z, .maybe_trigger_attack
    push hl
    ld hl, music_ch_volume_base
    call music_store_channel_byte
    pop hl
.maybe_trigger_attack:
    ld a, d
    or a
    ret z
    push hl
    call music_trigger_channel_attack
    pop hl
    ret

; ------------------------------------------------------------------
; music_apply_row
; Decode current order/pattern row and cache channel state for A/B/C.
; Input:  Runtime variables select track/order/pattern position
; Output: Channel note/instrument/volume caches updated
;         Row countdown reloaded and PSG refreshed once
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
music_apply_row:
    ld a, MUSIC_TRACK_ORDER_TABLE
    call music_read_track_word
    ld a, (music_order_pos)
    ld e, a
    ld d, 0
    add hl, de
    ld a, (hl)
    ld (music_pattern_index), a
    ld a, MUSIC_TRACK_PATTERN_TABLE
    call music_read_track_word
    ld a, (music_pattern_index)
    ld e, a
    ld d, 0
    add hl, de
    add hl, de
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    inc hl
    ld a, (hl)
    ld (music_pattern_rows), a
    ld a, e
    ld (music_pattern_ptr_l), a
    ld a, d
    ld (music_pattern_ptr_h), a
    ld h, d
    ld l, e
    ld a, (music_pattern_row)
    or a
    jp z, .row_ptr_ready
    ld b, a
.row_offset_loop:
    ld de, 12
    add hl, de
    djnz .row_offset_loop
.row_ptr_ready:
    xor a
    call music_apply_channel_cell
    ld a, 1
    call music_apply_channel_cell
    ld a, 2
    call music_apply_channel_cell
    ld a, (music_pattern_row)
    inc a
    ld d, a
    ld a, (music_pattern_rows)
    cp d
    jp z, .advance_order
    jp c, .advance_order
    ld a, d
    ld (music_pattern_row), a
    jp .row_done
.advance_order:
    xor a
    ld (music_pattern_row), a
    ld a, (music_order_pos)
    inc a
    ld d, a
    ld a, 1
    call music_read_track_byte
    cp d
    jp z, .end_of_order
    jp c, .end_of_order
    ld a, d
    ld (music_order_pos), a
    jp .row_done
.end_of_order:
    ld a, (music_loop)
    or a
    jp z, music_stop
    ld a, 2
    call music_read_track_byte
    ld (music_order_pos), a
.row_done:
    xor a
    call music_read_track_byte
    ld (music_row_frames), a
    ld (music_row_countdown), a
    call music_update_channel_effects
    ret

; ------------------------------------------------------------------
; music_update
; Advance the tracker once per game frame.
; Input:  None
; Output: Current channel PSG state refreshed; next row applied when due
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
music_update:
    ld a, (music_active)
    or a
    ret z
    ld a, (music_muted)
    or a
    ret nz
    ld a, (music_row_countdown)
    or a
    jp z, music_apply_row
    dec a
    ld (music_row_countdown), a
    jp z, music_apply_row
    call music_update_channel_effects
    ret

; ------------------------------------------------------------------
; music_update_channel_effects
; Rebuild mixer bits and push current cached channel state to PSG.
; Input:  music_ch_* caches already populated
; Output: PSG tone/volume registers updated for channels A/B/C
;         music_mixer_shadow rewritten with current enable bits
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
music_update_channel_effects:
    ld a, #3F
    ld (music_mixer_shadow), a
    ld c, 0
    call music_update_one_channel
    ld c, 1
    call music_update_one_channel
    ld c, 2
    call music_update_one_channel
    ld a, (music_mixer_shadow)
    call psg_set_mixer
    ret

; ------------------------------------------------------------------
; music_update_one_channel
; Apply one cached channel to PSG and update the mixer shadow bits.
; Input:  C = channel index (0=A, 1=B, 2=C)
; Output: Channel PSG tone/volume updated or silenced
;         music_mixer_shadow updated for that channel
; Destroys: AF, BC, DE, HL
; Preserves: Stack balance restored before return
; ------------------------------------------------------------------
music_update_one_channel:
    push bc
    push de
    push hl
    call music_resolve_channel_note_index
    cp #FF
    jp z, .silent_channel
    add a, a
    ld e, a
    ld d, 0
    ld hl, music_note_period_table
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ld a, c
    push bc
    call psg_set_tone
    pop bc
    call music_resolve_channel_volume
    ld a, c
    push bc
    call psg_set_volume
    pop bc
    ld d, 1
    ld e, 0
    call music_get_channel_instrument_ptr
    ld a, h
    or l
    jr z, .apply_mixer_bits
    ld a, (hl)
    and #01
    ld d, a
    ld a, (hl)
    and #02
    srl a
    ld e, a
    ld a, e
    or a
    jr z, .apply_mixer_bits
    push de
    call music_resolve_channel_noise
    call psg_set_noise
    pop de
.apply_mixer_bits:
    ld a, (music_mixer_shadow)
    ld b, a
    ld a, c
    cp 1
    jp z, .enable_b
    cp 2
    jp z, .enable_c
    ld a, b
    bit 0, d
    jr z, .a_tone_off
    and #3E
    jr .a_noise_gate
.a_tone_off:
    or #01
.a_noise_gate:
    bit 0, e
    jr z, .a_noise_off
    and #37
    jp .store_mixer
.a_noise_off:
    or #08
    jp .store_mixer
.enable_b:
    ld a, b
    bit 0, d
    jr z, .b_tone_off
    and #3D
    jr .b_noise_gate
.b_tone_off:
    or #02
.b_noise_gate:
    bit 0, e
    jr z, .b_noise_off
    and #2F
    jp .store_mixer
.b_noise_off:
    or #10
    jp .store_mixer
.enable_c:
    ld a, b
    bit 0, d
    jr z, .c_tone_off
    and #3B
    jr .c_noise_gate
.c_tone_off:
    or #04
.c_noise_gate:
    bit 0, e
    jr z, .c_noise_off
    and #1F
    jp .store_mixer
.c_noise_off:
    or #20
    jp .store_mixer
.silent_channel:
    ld b, 0
    ld a, c
    push bc
    call psg_set_volume
    pop bc
    ld a, (music_mixer_shadow)
    ld b, a
    ld a, c
    cp 1
    jp z, .disable_b
    cp 2
    jp z, .disable_c
    ld a, b
    or #09
    jp .store_mixer
.disable_b:
    ld a, b
    or #12
    jp .store_mixer
.disable_c:
    ld a, b
    or #24
.store_mixer:
    ld (music_mixer_shadow), a
    pop hl
    pop de
    pop bc
    ret

music_note_period_table:
    DW #1AB9,#1939,#17CF,#1679,#1536,#1405,#12E5,#11D6
    DW #10D6,#0FE4,#0EFF,#0E28,#0D5C,#0C9D,#0BE7,#0B3C
    DW #0A9B,#0A02,#0973,#08EB,#086B,#07F2,#0780,#0714
    DW #06AE,#064E,#05F4,#059E,#054D,#0501,#04B9,#0475
    DW #0435,#03F9,#03C0,#038A,#0357,#0327,#02FA,#02CF
    DW #02A7,#0281,#025D,#023B,#021B,#01FC,#01E0,#01C5
    DW #01AC,#0194,#017D,#0168,#0153,#0140,#012E,#011D
    DW #010D,#00FE,#00F0,#00E2,#00D6,#00CA,#00BE,#00B4
    DW #00AA,#00A0,#0097,#008F,#0087,#007F,#0078,#0071
    DW #006B,#0065,#005F,#005A,#0055,#0050,#004C,#0047
    DW #0043,#0040,#003C,#0039,#0035,#0032,#0030,#002D
    DW #002A,#0028,#0026,#0024,#0022,#0020,#001E,#001C

music_track_count:
    DB #00

music_track_ptr_table:
    DW 0

; ==================================================================
; END OF PSG SOUND SYSTEM
; ==================================================================


; ==================================================================
; SCROLL SYSTEM
; File: scroll.asm
; Description: Viewport management and screen scrolling for large worlds
; ==================================================================

; ==================================================================
; SCROLL SYSTEM CONSTANTS
; ==================================================================

SCREEN_WIDTH_TILES      EQU 32      ; MSX Screen 2 width in tiles
SCREEN_HEIGHT_TILES     EQU 24      ; MSX Screen 2 height in tiles
SCREEN_WIDTH_PIXELS     EQU 256     ; MSX Screen 2 width in pixels
SCREEN_HEIGHT_PIXELS    EQU 192     ; MSX Screen 2 height in pixels

; Note: NAMETBL (#1800) is already defined in constants.asm

; ==================================================================
; SCROLL SYSTEM INITIALIZATION
; ==================================================================

init_scroll_system:
    ; Initialize camera to (0, 0)
    xor a
    ld (camera_x), a
    ld (camera_x + 1), a
    ld (camera_y), a
    ld (camera_y + 1), a
    ld (camera_tile_x), a
    ld (camera_tile_y), a

    ; Set world dimensions (will be updated by level loader)
    ld a, SCREEN_WIDTH_TILES
    ld (world_width_tiles), a
    ld a, SCREEN_HEIGHT_TILES
    ld (world_height_tiles), a

    ; Clear dirty flag
    xor a
    ld (scroll_dirty_flag), a

    ret

; ==================================================================
; CAMERA CONTROL FUNCTIONS
; ==================================================================

; ------------------------------------------------------------------
; set_camera_position
; Set camera position in pixels (with bounds checking)
; Input:  HL = X position (pixels), DE = Y position (pixels)
; Destroys: AF, BC
; ------------------------------------------------------------------
set_camera_position:
    ; Bounds check X
    push hl
    push de

    ; Calculate max X = (world_width_tiles - SCREEN_WIDTH_TILES) * TILE_WIDTH
    ld a, (world_width_tiles)
    sub SCREEN_WIDTH_TILES
    jr c, .scroll_x_in_bounds   ; World smaller than screen

    ; A = tiles to scroll, multiply by tile width
    ld b, a
    ld a, 8
    call multiply_a_by_b        ; HL = max X

    ; Compare camera X with max X
    pop de
    pop bc                      ; BC = requested X
    push bc
    push de

    ; If requested X > max X, clamp to max X
    ld a, b
    cp h
    jr c, .scroll_x_clamped
    jr nz, .scroll_x_in_bounds
    ld a, c
    cp l
    jr c, .scroll_x_clamped
    jr .scroll_x_in_bounds

.scroll_x_clamped:
    ld b, h
    ld c, l
    jr .scroll_x_done

.scroll_x_in_bounds:
    pop de
    pop bc
    push bc
    push de

.scroll_x_done:
    ; Store camera X
    ld a, c
    ld (camera_x), a
    ld a, b
    ld (camera_x + 1), a

    ; Calculate camera_tile_x = camera_x / TILE_WIDTH
    
    ; Tile width is 8, shift right 3 times
    ld a, c
    srl b
    rra
    srl b
    rra
    srl b
    rra
    ld (camera_tile_x), a

    ; Bounds check Y
    pop de                      ; DE = requested Y
    pop bc

    ; Calculate max Y = (world_height_tiles - SCREEN_HEIGHT_TILES) * TILE_HEIGHT
    ld a, (world_height_tiles)
    sub SCREEN_HEIGHT_TILES
    jr c, .scroll_y_in_bounds   ; World smaller than screen

    ld b, a
    ld a, 8
    call multiply_a_by_b        ; HL = max Y

    ; If requested Y > max Y, clamp to max Y
    ld a, d
    cp h
    jr c, .scroll_y_clamped
    jr nz, .scroll_y_in_bounds
    ld a, e
    cp l
    jr c, .scroll_y_clamped
    jr .scroll_y_in_bounds

.scroll_y_clamped:
    ld d, h
    ld e, l

.scroll_y_in_bounds:
    ; Store camera Y
    ld a, e
    ld (camera_y), a
    ld a, d
    ld (camera_y + 1), a

    ; Calculate camera_tile_y = camera_y / TILE_HEIGHT
    
    ; Tile height is 8, shift right 3 times
    ld a, e
    srl d
    rra
    srl d
    rra
    srl d
    rra
    ld (camera_tile_y), a

    ; Mark viewport as dirty (needs redraw)
    ld a, 1
    ld (scroll_dirty_flag), a

    ret

; ------------------------------------------------------------------
; move_camera
; Move camera by delta (relative movement)
; Input:  B = delta X (signed), C = delta Y (signed)
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
move_camera:
    ; Get current camera position
    ld a, (camera_x)
    ld l, a
    ld a, (camera_x + 1)
    ld h, a                     ; HL = camera X

    ld a, (camera_y)
    ld e, a
    ld a, (camera_y + 1)
    ld d, a                     ; DE = camera Y

    ; Add delta X (signed 8-bit)
    ld a, b
    or a
    jp p, .move_positive_x      ; Positive delta

    ; Negative delta
    cpl
    inc a                       ; A = abs(delta)
    ld b, a
    ld a, l
    sub b
    ld l, a
    ld a, h
    sbc a, 0
    ld h, a
    jr .move_x_done

.move_positive_x:
    ld a, l
    add a, b
    ld l, a
    ld a, h
    adc a, 0
    ld h, a

.move_x_done:
    ; Add delta Y (signed 8-bit)
    ld a, c
    or a
    jp p, .move_positive_y

    ; Negative delta
    cpl
    inc a
    ld c, a
    ld a, e
    sub c
    ld e, a
    ld a, d
    sbc a, 0
    ld d, a
    jr .move_y_done

.move_positive_y:
    ld a, e
    add a, c
    ld e, a
    ld a, d
    adc a, 0
    ld d, a

.move_y_done:
    ; Set new camera position (with bounds checking)
    call set_camera_position
    ret

; ------------------------------------------------------------------
; center_camera_on_entity
; Center viewport on an entity (e.g. player)
; Input:  A = Entity index
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
center_camera_on_entity:
    ; Get entity position
    ld c, a
    ld b, 0
    ld hl, entity_x_pos
    add hl, bc
    ld a, (hl)                  ; A = entity X

    ld hl, entity_y_pos
    add hl, bc
    ld e, (hl)                  ; E = entity Y

    ; Calculate camera position to center entity
    ; camera_x = entity_x - (SCREEN_WIDTH / 2)
    sub 128                     ; Center horizontally
    ld l, a
    ld h, 0                     ; HL = camera X

    ; camera_y = entity_y - (SCREEN_HEIGHT / 2)
    ld a, e
    sub 96                      ; Center vertically
    ld e, a
    ld d, 0                     ; DE = camera Y

    ; Set camera position
    call set_camera_position
    ret

; ==================================================================
; VIEWPORT RENDERING
; ==================================================================

; ------------------------------------------------------------------
; update_scroll
; Update viewport if dirty flag is set
; Redraws visible tiles based on camera position
; ------------------------------------------------------------------
update_scroll:
    ; Check if viewport changed
    ld a, (scroll_dirty_flag)
    or a
    ret z                       ; Not dirty, nothing to do

    ; TODO: Implement efficient partial screen redraw
    ; For now: redraw entire visible area (simple but slow)
    call redraw_viewport

    ; Clear dirty flag
    xor a
    ld (scroll_dirty_flag), a
    ret

; ------------------------------------------------------------------
; redraw_viewport
; Redraw all visible tiles based on camera position
; This is the simple (slow) version that redraws everything
; ------------------------------------------------------------------
redraw_viewport:
    ; TODO: Implement full viewport redraw
    ; For each visible tile (32x24):
    ;   1. Calculate world tile coords (camera_tile + screen offset)
    ;   2. Read tile ID from world map
    ;   3. Write tile ID to Name Table

    ; Placeholder: Just return for now
    ret

; ==================================================================
; UTILITY FUNCTIONS
; ==================================================================

; ------------------------------------------------------------------
; multiply_a_by_b
; Multiply A by B (unsigned 8-bit)
; Input:  A = multiplicand, B = multiplier
; Output: HL = result (16-bit)
; Destroys: AF, BC
; ------------------------------------------------------------------
multiply_a_by_b:
    ld hl, 0
    ld c, a
.scroll_mul_loop:
    ld a, b
    or a
    ret z
    add hl, bc
    dec b
    jr .scroll_mul_loop

; ==================================================================
; END OF SCROLL SYSTEM
; ==================================================================


; ==================================================================
; ANIMATED TILES SYSTEM
; File: animtiles.asm
; Description: Background tile animation for water, lava, fire, etc.
; ==================================================================

; Auto-detected animated groups:
;   frame groups: 2
;   transform groups: 0

; ==================================================================
; ANIMATED TILES CONSTANTS
; ==================================================================

; Animation speeds (in frames)
ANIM_SPEED_SLOW         EQU 15      ; ~250ms (water)
ANIM_SPEED_MEDIUM       EQU 8       ; ~133ms (lava)
ANIM_SPEED_FAST         EQU 4       ; ~66ms (fire)

; Maximum animated tiles
MAX_ANIM_TILES          EQU 2
ANIM_TILE_ENTRY_SIZE    EQU 7       ; char, chars, frames, speed, bytesPerFrame, ptr(2)
ANIM_TRANS_ENTRY_SIZE   EQU 4       ; char, chars, opCode, flags
ANIM_TILE_DATA_BANK     EQU 0       ; Deprecated: anim data is local to animtiles code bank

; ==================================================================
; ANIMATED TILES INITIALIZATION
; ==================================================================

init_animated_tiles:
    ; Initialize animation variables
    xor a
    ld (anim_tile_timer), a
    ld (anim_tile_frame), a

    ; Set default global animation speed
    ld a, 1
    ld (anim_tile_speed), a

    ; Upload initial animation frame state immediately
    call update_animated_tiles_vram

    ret

; ==================================================================
; ANIMATED TILES UPDATE FUNCTIONS
; ==================================================================

; ------------------------------------------------------------------
; update_animated_tiles
; Update animation frame and redraw animated tiles if needed
; Call this every frame from main loop
; ------------------------------------------------------------------
update_animated_tiles:
    ; Skip animation work on screens with no animated tile groups
    ld a, (current_screen_anim_group_count)
    or a
    ret z

    ; Increment timer
    ld a, (anim_tile_timer)
    inc a
    ld (anim_tile_timer), a

    ; Check if it's time to advance frame
    ld b, a
    ld a, (anim_tile_speed)
    or a
    jr nz, .anim_speed_ok
    ld a, 1
    ld (anim_tile_speed), a
.anim_speed_ok:
    cp b
    ret nc                          ; Not yet time to update (timer < speed)

    ; Reset timer
    xor a
    ld (anim_tile_timer), a

    ; Advance global animation counter
    ld a, (anim_tile_frame)
    inc a
    ld (anim_tile_frame), a

    ; Update all animated tiles in VRAM
    call update_animated_tiles_vram

    ret

; ------------------------------------------------------------------
; update_animated_tiles_vram
; Update pattern data in VRAM for all animated tiles
; This updates the actual tile patterns based on current frame
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
update_animated_tiles_vram:
    ; Protect VDP port sequence from ISR VRAM writes.
    ; Always re-enables on exit (see FAST_LDIRVM note on LD A,I bug).
    di
    ld hl, anim_tile_table

.anim_vram_loop:
    ld a, (hl)                      ; A = target char code
    cp 255
    jp z, .anim_vram_done

    push af                         ; Save target char code
    inc hl
    ld a, (hl)                      ; A = chars per tile
    push af
    inc hl
    ld b, (hl)                      ; B = frame count
    inc hl
    inc hl                          ; Skip speed byte (reserved)
    ld c, (hl)                      ; C = bytes per frame
    inc hl
    ld e, (hl)                      ; DE = data pointer
    inc hl
    ld d, (hl)
    inc hl                          ; HL = next table entry
    push hl
    ex de, hl                       ; HL = data pointer

    ; frame = global_frame % frame_count
    ; Fast path for power-of-two frame counts: frame & (count-1)
    ld a, b
    dec a
    ld d, a
    and b
    jr nz, .anim_mod_slow
    ld a, (anim_tile_frame)
    and d
    jr .anim_mod_done
.anim_mod_slow:
    ld a, (anim_tile_frame)
.anim_mod_loop:
    cp b
    jr c, .anim_mod_done
    sub b
    jr .anim_mod_loop
.anim_mod_done:

    ; DE = frame offset (frame * bytes_per_frame)
    ld b, a
    ld d, 0
    ld e, 0
.anim_mul_loop:
    ld a, b
    or a
    jr z, .anim_mul_done
    ld a, e
    add a, c
    ld e, a
    ld a, d
    adc a, 0
    ld d, a
    dec b
    jr .anim_mul_loop
.anim_mul_done:
    add hl, de                      ; HL = frame data pointer

    pop de                          ; DE = next table entry pointer
    pop af
    ld b, a                         ; B = chars per tile
    pop af
    ld c, a                         ; C = target char code
    push de

.anim_char_loop:
    ld a, b
    or a
    jr z, .anim_char_done

    push bc
    push hl
    ld a, c
    call anim_upload_char_frame
    pop hl
    pop bc

    ld de, 16
    add hl, de                      ; Next char frame chunk
    inc c                           ; Next target char code
    dec b
    jr .anim_char_loop

.anim_char_done:
    pop de
    ex de, hl                       ; HL = next table entry
    jp .anim_vram_loop

.anim_vram_done:

    ei
    ret

; ------------------------------------------------------------------
; set_animation_speed
; Set global animation speed for all animated tiles
; Input:  A = Speed (frames between updates)
; ------------------------------------------------------------------
set_animation_speed:
    or a
    jr nz, .anim_speed_store
    ld a, 1
.anim_speed_store:
    ld (anim_tile_speed), a
    ret

; ------------------------------------------------------------------
; anim_copy_8_bytes
; Copy 8 bytes from CPU memory to VRAM
; Input: DE = source pointer, HL = VRAM destination
; Destroys: AF, BC, DE, HL
; ------------------------------------------------------------------
anim_copy_8_bytes:
    ld b, 8
.anim_copy_loop:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_copy_loop

    ret

; ==================================================================
; anim_upload_char_frame
; Upload one animated char (pattern + color) to all 3 Screen 2 banks
; Input: A = target char code, HL = source frame chunk (16 bytes)
; Source layout: 8 pattern bytes + 8 color bytes
; Destroys: AF, BC, DE, HL
; ==================================================================
anim_upload_char_frame:
    push af
    push bc
    push de
    push hl

    ; BC = target char offset (charCode * 8)
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    ld b, h
    ld c, l

    pop hl
    ex de, hl                      ; DE = source pattern pointer

    ; Pattern bank 0
    push de
    ld hl, CHRTBL2
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Pattern bank 1
    push de
    ld hl, CHRTBL2 + #800
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Pattern bank 2
    ld hl, CHRTBL2 + #1000
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc

    ; DE now points to color bytes (source + 8)
    ; Color bank 0
    push de
    ld hl, CLRTBL2
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Color bank 1
    push de
    ld hl, CLRTBL2 + #800
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc
    pop de

    ; Color bank 2
    ld hl, CLRTBL2 + #1000
    add hl, bc
    push bc
    call anim_copy_8_bytes
    pop bc

    pop de
    pop bc
    pop af
    ret

; ==================================================================
; TRANSFORM MODE ROUTINES (Z80 runtime bit/row transforms)
; ==================================================================

; ------------------------------------------------------------------
; Routine: update_animated_transform_tiles_vram
; Purpose:
;   Applies Z80 transform operations directly on tile bytes in VRAM.
; Input:
;   None
; Output:
;   None
; Modifies:
;   AF, BC, DE, HL
; Preserves:
;   IX, IY, SP
; Flags:
;   Not preserved
; Stack:
;   Uses PUSH/POP HL, BC and DE internally
; ------------------------------------------------------------------
update_animated_transform_tiles_vram:
    ret

; ------------------------------------------------------------------
; Routine: anim_transform_char_frame
; Purpose:
;   Transform one character pattern in all SCREEN 2 banks.
; Input:
;   A = character code
;   D = transform operation code
;   (anim_tile_transform_flags).bit0 = transform color rows too
; Output:
;   None
; Modifies:
;   AF, BC, DE, HL
; Preserves:
;   IX, IY, SP
; Flags:
;   Not preserved
; Stack:
;   Pushes/pops BC, DE and HL
; ------------------------------------------------------------------
anim_transform_char_frame:
    push bc
    push de
    push hl

    ; BC = charCode * 8 (row offset in pattern/color tables)
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    ld b, h
    ld c, l

    ; Save opcode D to scratch RAM so anim_transform_vram_block can reload it
    ; after DE is reused internally as a pointer.
    ld a, d
    ld (anim_tile_transform_flags + 1), a

    ; Pattern banks: read bank 0 once and mirror the transformed result to all 3
    ; SCREEN 2 banks to keep animation phase identical across thirds.
    ld hl, CHRTBL2
    add hl, bc
    call anim_transform_vram_block

    ; anim_transform_vram_block reuses DE internally, so reload the opcode
    ; from scratch RAM before deciding whether color rows also need a transform.
    ld a, (anim_tile_transform_flags + 1)
    cp 5
    jr c, .anim_transform_char_done

    ld a, (anim_tile_transform_flags)
    and 1
    jr z, .anim_transform_char_done

    ; Color banks: same approach, read bank 0 and mirror to all 3 banks.
    ld a, (anim_tile_transform_flags + 1)
    ld d, a
    ld hl, CLRTBL2
    add hl, bc
    call anim_transform_vram_block

.anim_transform_char_done:
    pop hl
    pop de
    pop bc
    ret

; ------------------------------------------------------------------
; Routine: anim_transform_vram_block
; Purpose:
;   Apply transform to one 8-byte VRAM block (one char rows table).
; Input:
;   HL = VRAM base address for row 0 (8 consecutive bytes)
;   D  = operation code:
;        1 rotate_left  (RLCA)
;        2 rotate_right (RRCA)
;        3 shift_left   (SLA)
;        4 shift_right  (SRL)
;        5 shift_up rows
;        6 shift_down rows
;        7 swap top/bottom row
; Output:
;   None
; Modifies:
;   AF, BC, DE, HL
; Preserves:
;   IX, IY, SP
; Flags:
;   Not preserved
; Stack:
;   Uses stack while reading row bytes
; ------------------------------------------------------------------
anim_transform_vram_block:
    ; HL = VRAM base address for bank 0. The routine captures the source rows
    ; from bank 0, transforms them in RAM, then writes the same result to the
    ; three SCREEN 2 banks. This prevents per-bank phase drift.
    ld a, d
    cp 5
    jp nc, .anim_transform_vertical

    ; Step 1: Read bank 0 into the RAM buffer.
    push hl
    ld de, anim_tile_row_buffer
    ld b, 8
.anim_read_horiz_loop:
    push hl
    call FAST_RDVRM                 ; A = row byte from VRAM[HL]
    pop hl
    ld (de), a
    inc de
    inc hl
    djnz .anim_read_horiz_loop
    pop hl

    ; Step 2: Transform the buffered bytes in RAM.
    ld de, anim_tile_row_buffer
    ld b, 8
    ld a, (anim_tile_transform_flags + 1)
    ld c, a
.anim_apply_horiz_loop:
    ld a, (de)
    push de
    push bc
    ld b, a
    ld a, c
    cp 1
    jr nz, .anim_not_rl3
    ld a, b
    rlca
    jr .anim_store_h
.anim_not_rl3:
    cp 2
    jr nz, .anim_not_rr3
    ld a, b
    rrca
    jr .anim_store_h
.anim_not_rr3:
    cp 3
    jr nz, .anim_not_sla3
    ld a, b
    sla a
    jr .anim_store_h
.anim_not_sla3:
    ld a, b
    srl a
.anim_store_h:
    pop bc
    pop de
    ld (de), a
    inc de
    djnz .anim_apply_horiz_loop

    ; Step 3: Mirror the transformed buffer to the 3 pattern/color banks.
    push hl
    ld de, anim_tile_row_buffer
    ld b, 8
.anim_write_bank0_loop:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_bank0_loop
    pop hl

    push hl
    ld de, #0800
    add hl, de
    ld de, anim_tile_row_buffer
    ld b, 8
.anim_write_bank1_loop:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_bank1_loop
    pop hl

    ld de, #1000
    add hl, de
    ld de, anim_tile_row_buffer
    ld b, 8
.anim_write_bank2_loop:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_bank2_loop
    ret

.anim_transform_vertical:
    ; Step 1: Read bank 0 into the RAM buffer.
    push de
    ld de, anim_tile_row_buffer
    ld b, 8
.anim_read_rows_loop:
    push hl
    call FAST_RDVRM                 ; A = row byte
    pop hl
    ld (de), a
    inc de
    inc hl
    djnz .anim_read_rows_loop
    pop de

    ; Restore HL to the start of bank 0 and reload the opcode scratch byte.
    ld de, #FFF8
    add hl, de

    ld a, (anim_tile_transform_flags + 1)
    cp 5
    jr nz, .anim_not_shift_up

    ; shift_up: row0<-row1 ... row6<-row7 row7<-row0(original)
    push hl
    ld de, anim_tile_row_buffer + 1
    ld b, 7
.anim_write_up_b0:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_up_b0
    ld a, (anim_tile_row_buffer)
    call FAST_WRTVRM
    pop hl

    push hl
    ld de, #0800
    add hl, de
    ld de, anim_tile_row_buffer + 1
    ld b, 7
.anim_write_up_b1:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_up_b1
    ld a, (anim_tile_row_buffer)
    call FAST_WRTVRM
    pop hl

    ld de, #1000
    add hl, de
    ld de, anim_tile_row_buffer + 1
    ld b, 7
.anim_write_up_b2:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_up_b2
    ld a, (anim_tile_row_buffer)
    call FAST_WRTVRM
    ret

.anim_not_shift_up:
    cp 6
    jr nz, .anim_not_shift_down

    ; shift_down: row0<-row7(original) row1<-row0 ... row7<-row6
    push hl
    ld a, (anim_tile_row_buffer + 7)
    call FAST_WRTVRM
    inc hl
    ld de, anim_tile_row_buffer
    ld b, 7
.anim_write_dn_b0:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_dn_b0
    pop hl

    push hl
    ld de, #0800
    add hl, de
    ld a, (anim_tile_row_buffer + 7)
    call FAST_WRTVRM
    inc hl
    ld de, anim_tile_row_buffer
    ld b, 7
.anim_write_dn_b1:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_dn_b1
    pop hl

    ld de, #1000
    add hl, de
    ld a, (anim_tile_row_buffer + 7)
    call FAST_WRTVRM
    inc hl
    ld de, anim_tile_row_buffer
    ld b, 7
.anim_write_dn_b2:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_dn_b2
    ret

.anim_not_shift_down:
    ; swap_top_bottom: row0<->row7, middle rows unchanged
    push hl
    ld a, (anim_tile_row_buffer + 7)
    call FAST_WRTVRM
    inc hl
    ld de, anim_tile_row_buffer + 1
    ld b, 6
.anim_write_sw_mid_b0:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_sw_mid_b0
    ld a, (anim_tile_row_buffer)
    call FAST_WRTVRM
    pop hl

    push hl
    ld de, #0800
    add hl, de
    ld a, (anim_tile_row_buffer + 7)
    call FAST_WRTVRM
    inc hl
    ld de, anim_tile_row_buffer + 1
    ld b, 6
.anim_write_sw_mid_b1:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_sw_mid_b1
    ld a, (anim_tile_row_buffer)
    call FAST_WRTVRM
    pop hl

    ld de, #1000
    add hl, de
    ld a, (anim_tile_row_buffer + 7)
    call FAST_WRTVRM
    inc hl
    ld de, anim_tile_row_buffer + 1
    ld b, 6
.anim_write_sw_mid_b2:
    ld a, (de)
    call FAST_WRTVRM
    inc de
    inc hl
    djnz .anim_write_sw_mid_b2
    ld a, (anim_tile_row_buffer)
    call FAST_WRTVRM
    ret

; ==================================================================
; ANIMATED TILE DEFINITIONS (AUTO-GENERATED)
; ==================================================================

; ------------------------------------------------------------------
; Animated tile mapping table
; Format:
;   db targetCharCode, charsPerTile, numFrames, speed, bytesPerFrame
;   dw frameDataPointer
; ------------------------------------------------------------------
anim_tile_table:
    db 129, 1, 2, 1, 16    ; New Boss_part_4_4 -> tile tile_boss_1777550194409
    dw anim_group_0_new_boss_part_4_4
    db 138, 1, 2, 1, 16    ; New Boss_part_4_4_mirror_h -> tile tile_boss_mirror_horizontal_1777551176375
    dw anim_group_1_new_boss_part_4_4_mirror_h
    db 255                          ; End marker

; ------------------------------------------------------------------
; Transform tile mapping table
; Format:
;   db targetCharCode, charsPerTile, opCode, flags
; flags:
;   bit0 = apply vertical transform on color rows
; ------------------------------------------------------------------
anim_transform_table:
    ; Transform groups are precomputed as frame data in anim_tile_table
    db 255                          ; End marker

; ==================================================================
; ANIMATION FRAME DATA
; ==================================================================
anim_group_0_new_boss_part_4_4:
    ; Group "New Boss_part_4_4" targetChar=129 chars=1
    ; Frame 0: New Boss_part_4_4
    db #7E, #FF, #FF, #FF, #FF, #FF, #FF, #7E, #E1, #E1, #E1, #E1, #F1, #F1, #F1, #F1
    ; Frame 1: New Boss_part_4_4
    db #FF, #BF, #FC, #F8, #F8, #FC, #BF, #FE, #E1, #E1, #E1, #E1, #E1, #E1, #E1, #E1

anim_group_1_new_boss_part_4_4_mirror_h:
    ; Group "New Boss_part_4_4_mirror_h" targetChar=138 chars=1
    ; Frame 0: New Boss_part_4_4_mirror_h
    db #FF, #DD, #FF, #FF, #FF, #EF, #FD, #7F, #E1, #E1, #E1, #E1, #E1, #E1, #E1, #E1
    ; Frame 1: New Boss_part_4_4_mirror_h
    db #FF, #FD, #3F, #1F, #1F, #3F, #FD, #7F, #F1, #F1, #F1, #F1, #F1, #F1, #F1, #F1


; ------------------------------------------------------------------
; register_animated_tile
; Runtime registration is not supported in this generator version.
; Input:  A = Tile ID to animate
;         B = Number of frames (2-4)
;         C = Animation speed
; Output: A = 0 if failed (table full), 1 if success
; Destroys: AF, DE, HL
; ------------------------------------------------------------------
register_animated_tile:
    xor a                           ; Not supported (static generated table)
    ret

; ------------------------------------------------------------------
; get_tile_animation_frame
; Get current animation frame for a tile
; Input:  A = target char code
; Output: A = Current frame index (mod numFrames), or 0 if not animated
; Destroys: BC, DE, HL
; ------------------------------------------------------------------
get_tile_animation_frame:
    ld c, a                         ; C = char code to search
    ld hl, anim_tile_table

.anim_search_loop:
    ld a, (hl)
    cp 255
    jr z, .anim_not_found
    cp c
    jr z, .anim_found_tile

    ld de, ANIM_TILE_ENTRY_SIZE
    add hl, de
    jr .anim_search_loop

.anim_found_tile:
    inc hl
    inc hl
    ld b, (hl)                      ; B = numFrames
    ld a, (anim_tile_frame)
.anim_found_mod:
    cp b
    jr c, .anim_found_done
    sub b
    jr .anim_found_mod
.anim_found_done:
    ret

.anim_not_found:
    xor a
    ret

; ==================================================================
; END OF ANIMATED TILES SYSTEM
; ==================================================================


; ==================================================================
; BOSSES
; Generated boss data for tile bosses, neck chains, crush movement, projectiles, sine waves, boomerangs, rocks, char lasers, meteors, falling blocks and bombs.
; ==================================================================

BOSS_COUNT EQU 1
BOSS_DIR_LEFT EQU 0
BOSS_DIR_RIGHT EQU 1
BOSS_DIR_UP EQU 2
BOSS_DIR_DOWN EQU 3
BOSS_ATTACK_PROJECTILE EQU 0
BOSS_ATTACK_MELEE EQU 1
BOSS_ATTACK_SPECIAL EQU 2
BOSS_ATTACK_PATTERN EQU 3
BOSS_ATTACK_METEOR EQU 4
BOSS_ATTACK_BOMB EQU 5
BOSS_ATTACK_BOOMERANG EQU 6
BOSS_ATTACK_ROCK EQU 7
BOSS_ATTACK_LASER EQU 8
BOSS_ATTACK_SINE_WAVE EQU 9
BOSS_ATTACK_HOMING_MISSILE EQU 10
BOSS_ATTACK_SLAM_ROCKS EQU 11
BOSS_ATTACK_FALLING_BLOCKS EQU 12

; Register Contract:
; input: none
; output: boss_runtime_tick and boss_active reset to 0
; clobbers: A
init_boss_system:
    xor a
    ld (boss_runtime_tick), a
    ld (boss_active), a
    ld (boss_visual_dirty), a
    ld (boss_projectile_active), a
    ld (boss_slam_rocks_active), a
    ld (boss_falling_blocks_active), a
    ld (boss_update_timer), a
    ld a, 1
    ld (boss_update_interval), a
    ret

; Register Contract:
; input: none
; output: boss_runtime_tick increments; active boss behavior is stepped and exposed old cells are restored only when moved
; clobbers: AF, BC, DE, HL
; preserves: IX
update_boss_system:
    push ix
    ld a, (boss_runtime_tick)
    inc a
    ld (boss_runtime_tick), a
    ld a, (boss_active)
    or a
    jp z, .ubs_done
    ld a, (boss_update_timer)
    or a
    jp z, .ubs_update_due
    dec a
    ld (boss_update_timer), a
    jp .ubs_done
.ubs_update_due:
    ld a, (boss_update_interval)
    or a
    jp nz, .ubs_update_interval_ok
    ld a, 1
    ld (boss_update_interval), a
.ubs_update_interval_ok:
    dec a
    ld (boss_update_timer), a
    call update_boss_behavior
    call update_boss_projectile_runtime
    call update_boss_slam_rocks_runtime
    call update_boss_falling_blocks_runtime
    ld a, (boss_x_char)
    ld b, a
    ld a, (boss_prev_x_char)
    cp b
    jp nz, .ubs_redraw
    ld a, (boss_y_char)
    ld b, a
    ld a, (boss_prev_y_char)
    cp b
    jp nz, .ubs_redraw
    ld a, (boss_visual_dirty)
    or a
    jp z, .ubs_done
.ubs_redraw:
    call draw_active_boss_tiles
    call restore_active_boss_tiles_exposed
    xor a
    ld (boss_visual_dirty), a
    ld a, (boss_x_char)
    ld (boss_prev_x_char), a
    ld a, (boss_y_char)
    ld (boss_prev_y_char), a
.ubs_done:
    pop ix
    ret

; ------------------------------------------------------------------
; Boss attack record layout
; ------------------------------------------------------------------
BOSS_ATTACK_TYPE_OFF EQU 0
BOSS_ATTACK_SPRITE_OFF EQU 1
BOSS_ATTACK_DAMAGE_OFF EQU 2
BOSS_ATTACK_SPEED_OFF EQU 3
BOSS_ATTACK_DIR_OFF EQU 4
BOSS_ATTACK_OFFX_OFF EQU 5
BOSS_ATTACK_OFFY_OFF EQU 6
BOSS_ATTACK_RANGE_LO_OFF EQU 7
BOSS_ATTACK_COOLDOWN_LO_OFF EQU 9
BOSS_ATTACK_DURATION_LO_OFF EQU 11
BOSS_ATTACK_METEOR_COUNT_OFF EQU 13
BOSS_ATTACK_METEOR_SPREAD_OFF EQU 14
BOSS_ATTACK_METEOR_WARN_OFF EQU 15
BOSS_ATTACK_COOLDOWN_FRAMES_OFF EQU 16
BOSS_ATTACK_METEOR_COOLDOWN_FRAMES_OFF EQU 16
BOSS_ATTACK_BOMB_COUNT_OFF EQU 17
BOSS_ATTACK_BOMB_SPREAD_OFF EQU 18
BOSS_ATTACK_BOMB_FUSE_OFF EQU 19
BOSS_ATTACK_EXPLOSION_RADIUS_OFF EQU 20
BOSS_ATTACK_EXPLOSION_DURATION_OFF EQU 21
BOSS_ATTACK_EXPLOSION_SPRITE_OFF EQU 22
BOSS_ATTACK_ARC_HEIGHT_OFF EQU 23
BOSS_ATTACK_LASER_TILE_OFF EQU 24
BOSS_ATTACK_LASER_LENGTH_OFF EQU 25
BOSS_ATTACK_LASER_DURATION_OFF EQU 26
BOSS_ATTACK_WAVE_AMPLITUDE_OFF EQU 27
BOSS_ATTACK_WAVE_FREQUENCY_OFF EQU 28
BOSS_ATTACK_HOMING_TURN_STEP_OFF EQU 29
BOSS_ATTACK_SLAM_RISE_CHARS_OFF EQU 30
BOSS_ATTACK_SLAM_WINDUP_FRAMES_OFF EQU 31
BOSS_ATTACK_SLAM_FRAMES_OFF EQU 32
BOSS_ATTACK_SLAM_HOLD_FRAMES_OFF EQU 33
BOSS_ATTACK_BLOCK_TILE_OFF EQU 34
BOSS_ATTACK_BLOCK_LANDING_Y_OFF EQU 35
BOSS_ATTACK_BLOCK_BEHAVIOR_OFF EQU 36
BOSS_ATTACK_RECORD_SIZE EQU 37

; ------------------------------------------------------------------
; Boss phase and screen placement runtime layout
; ------------------------------------------------------------------
BOSS_PHASE_BUILD_TYPE_OFF EQU 1
BOSS_PHASE_WIDTH_OFF EQU 2
BOSS_PHASE_HEIGHT_OFF EQU 3
BOSS_PHASE_TILE_MATRIX_PTR_OFF EQU 4
BOSS_PHASE_BEHAVIOR_PTR_OFF EQU 14
BOSS_PHASE_FORM_TABLE_PTR_OFF EQU 16
BOSS_BUILD_TYPE_TILE EQU 0
BOSS_RUNTIME_PLACEMENT_PHASE_TABLE_OFF EQU 0
BOSS_RUNTIME_PLACEMENT_ATTACK_TABLE_OFF EQU 2
BOSS_RUNTIME_PLACEMENT_X_OFF EQU 4
BOSS_RUNTIME_PLACEMENT_Y_OFF EQU 5
BOSS_RUNTIME_PLACEMENT_INITIAL_PHASE_OFF EQU 6
BOSS_RUNTIME_PLACEMENT_FLAGS_OFF EQU 7
BOSS_RUNTIME_PLACEMENT_UPDATE_INTERVAL_OFF EQU 8
BOSS_RUNTIME_PLACEMENT_FLAG_ENABLED EQU #01
BOSS_BEHAVIOR_WAIT EQU 0
BOSS_BEHAVIOR_MOVE_TO EQU 1
BOSS_BEHAVIOR_ATTACK EQU 2
BOSS_BEHAVIOR_SLAM EQU 3
BOSS_BEHAVIOR_PROTECT EQU 4
BOSS_BEHAVIOR_SHIELD EQU 5
BOSS_BEHAVIOR_SET_FORM EQU 6
BOSS_BEHAVIOR_ANIMATE_FORM EQU 7
BOSS_BEHAVIOR_LOOP EQU 8
BOSS_BEHAVIOR_TARGET_FIXED EQU 0
BOSS_BEHAVIOR_TARGET_PLAYER_CURRENT EQU 1
BOSS_BEHAVIOR_TARGET_PLAYER_PREDICTED EQU 2
BOSS_BEHAVIOR_TARGET_PLAYER_LAST_KNOWN EQU 3
BOSS_BEHAVIOR_TARGET_BOSS_RELATIVE EQU 4
BOSS_BEHAVIOR_ACTION_SIZE EQU 8

; Register Contract:
; input: current_screen_boss_count/current_screen_boss_table identify the current screen placement table
; output: first enabled boss placement is copied to boss runtime RAM and drawn to the SCREEN 2 name table
; clobbers: AF, BC, DE, HL
; preserves: IX
init_screen_boss_from_current_screen:
    push ix
    xor a
    ld (boss_active), a
    ld (boss_projectile_active), a
    ld (boss_slam_rocks_active), a
    ld a, (current_screen_boss_count)
    or a
    jp z, .isb_done

    ld hl, (current_screen_boss_table)
    ld e, (hl)
    inc hl
    ld d, (hl)
    inc hl
    ld (boss_phase_table_ptr), de
    ld e, (hl)
    inc hl
    ld d, (hl)
    inc hl
    ld (boss_attack_table_ptr), de
    ld a, (hl)
    inc hl
    ld (boss_x_char), a
    ld (boss_prev_x_char), a
    ld a, (hl)
    inc hl
    ld (boss_y_char), a
    ld (boss_prev_y_char), a
    ld a, (hl)
    inc hl
    ld (boss_initial_phase_index), a
    ld a, (hl)
    inc hl
    and BOSS_RUNTIME_PLACEMENT_FLAG_ENABLED
    jp z, .isb_done
    ld a, (hl)
    or a
    jp nz, .isb_update_interval_ok
    ld a, 1
.isb_update_interval_ok:
    ld (boss_update_interval), a
    xor a
    ld (boss_update_timer), a

    call boss_resolve_initial_phase
    call boss_init_behavior_state
    ld a, 1
    ld (boss_active), a
    call draw_active_boss_tiles

.isb_done:
    pop ix
    ret

; Register Contract:
; input: boss_phase_table_ptr and boss_initial_phase_index
; output: boss_phase_ptr, boss_tile_matrix_ptr, boss_width and boss_height populated from the selected phase record
; clobbers: AF, DE, HL, IX
boss_resolve_initial_phase:
    ld hl, (boss_phase_table_ptr)
    ld a, (boss_initial_phase_index)
    add a, a
    ld e, a
    ld d, 0
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld (boss_phase_ptr), de
    push de
    pop ix
    ld a, (ix+2)
    ld (boss_width), a
    ld a, (ix+3)
    ld (boss_height), a
    ld e, (ix+4)
    ld d, (ix+5)
    ld (boss_tile_matrix_ptr), de
    ld e, (ix+14)
    ld d, (ix+15)
    ld (boss_behavior_table_ptr), de
    ld e, (ix+16)
    ld d, (ix+17)
    ld (boss_form_table_ptr), de
    ret

; Register Contract:
; input: boss_behavior_table_ptr resolved from the active phase
; output: behavior interpreter counters reset for this phase
; clobbers: AF, HL
boss_init_behavior_state:
    ld hl, (boss_behavior_table_ptr)
    ld a, h
    cp #FF
    jp nz, .bibs_has_table
    ld a, l
    cp #FF
    jp nz, .bibs_has_table
    xor a
    ld (boss_behavior_count), a
    ld (boss_behavior_index), a
    ld (boss_behavior_timer), a
    ret
.bibs_has_table:
    ld a, (hl)
    ld (boss_behavior_count), a
    xor a
    ld (boss_behavior_index), a
    ld (boss_behavior_timer), a
    ret

; Register Contract:
; input: active boss runtime RAM populated by init_screen_boss_from_current_screen
; output: non-empty boss tile chars are written into the SCREEN 2 name table
; clobbers: AF, BC, DE, HL
; preserves: IX
draw_active_boss_tiles:
    push ix
    ld a, (boss_active)
    or a
    jp z, .dabt_done
    ld a, (boss_width)
    or a
    jp z, .dabt_done
    ld a, (boss_height)
    or a
    jp z, .dabt_done

    xor a
    ld (boss_draw_row), a
.dabt_row_loop:
    ld a, (boss_draw_row)
    ld c, a
    ld a, (boss_height)
    cp c
    jp z, .dabt_done

    xor a
    ld (boss_draw_col), a
.dabt_col_loop:
    ld a, (boss_draw_col)
    ld c, a
    ld a, (boss_width)
    cp c
    jp z, .dabt_next_row

    call boss_get_active_tile_char
    cp #FF
    jp z, .dabt_skip_cell
    ld (boss_draw_char), a

    ld a, (boss_x_char)
    ld b, a
    ld a, (boss_draw_col)
    add a, b
    cp 32
    jp nc, .dabt_skip_cell
    ld (boss_draw_screen_x), a

    ld a, (boss_y_char)
    ld b, a
    ld a, (boss_draw_row)
    add a, b
    cp 24
    jp nc, .dabt_skip_cell
    ld (boss_draw_screen_y), a
    call boss_draw_write_cell

.dabt_skip_cell:
    ld a, (boss_draw_col)
    inc a
    ld (boss_draw_col), a
    jp .dabt_col_loop

.dabt_next_row:
    ld a, (boss_draw_row)
    inc a
    ld (boss_draw_row), a
    jp .dabt_row_loop

.dabt_done:
    pop ix
    ret

; Register Contract:
; input: boss_prev_x_char/boss_prev_y_char and active boss dimensions
; output: previous boss footprint restored from runtime_screen_layout into SCREEN 2 name table
; clobbers: AF, BC, DE, HL
; preserves: IX
restore_active_boss_tiles:
    push ix
    ld a, (boss_active)
    or a
    jp z, .rabt_done
    ld a, (boss_width)
    or a
    jp z, .rabt_done
    ld a, (boss_height)
    or a
    jp z, .rabt_done

    xor a
    ld (boss_draw_row), a
.rabt_row_loop:
    ld a, (boss_draw_row)
    ld c, a
    ld a, (boss_height)
    cp c
    jp z, .rabt_done

    xor a
    ld (boss_draw_col), a
.rabt_col_loop:
    ld a, (boss_draw_col)
    ld c, a
    ld a, (boss_width)
    cp c
    jp z, .rabt_next_row

    ld a, (boss_prev_x_char)
    ld b, a
    ld a, (boss_draw_col)
    add a, b
    cp 32
    jp nc, .rabt_skip_cell
    ld (boss_draw_screen_x), a

    ld a, (boss_prev_y_char)
    ld b, a
    ld a, (boss_draw_row)
    add a, b
    cp 24
    jp nc, .rabt_skip_cell
    ld (boss_draw_screen_y), a
    call boss_get_runtime_layout_char
    ld (boss_draw_char), a
    call boss_draw_write_cell

.rabt_skip_cell:
    ld a, (boss_draw_col)
    inc a
    ld (boss_draw_col), a
    jp .rabt_col_loop

.rabt_next_row:
    ld a, (boss_draw_row)
    inc a
    ld (boss_draw_row), a
    jp .rabt_row_loop

.rabt_done:
    pop ix
    ret

; Register Contract:
; input: boss_prev_x_char/boss_prev_y_char, current boss_x_char/boss_y_char and active boss dimensions
; output: only previous boss cells not covered by the current opaque boss shape are restored from runtime_screen_layout
; clobbers: AF, BC, DE, HL
; preserves: IX
restore_active_boss_tiles_exposed:
    push ix
    ld a, (boss_active)
    or a
    jp z, .rabte_done
    ld a, (boss_width)
    or a
    jp z, .rabte_done
    ld a, (boss_height)
    or a
    jp z, .rabte_done

    xor a
    ld (boss_restore_row), a
.rabte_row_loop:
    ld a, (boss_restore_row)
    ld c, a
    ld a, (boss_height)
    cp c
    jp z, .rabte_done

    xor a
    ld (boss_restore_col), a
.rabte_col_loop:
    ld a, (boss_restore_col)
    ld c, a
    ld a, (boss_width)
    cp c
    jp z, .rabte_next_row

    ld a, (boss_prev_x_char)
    ld b, a
    ld a, (boss_restore_col)
    add a, b
    cp 32
    jp nc, .rabte_skip_cell
    ld (boss_draw_screen_x), a

    ld a, (boss_prev_y_char)
    ld b, a
    ld a, (boss_restore_row)
    add a, b
    cp 24
    jp nc, .rabte_skip_cell
    ld (boss_draw_screen_y), a

    call boss_current_shape_covers_draw_cell
    jp nz, .rabte_skip_cell
    call boss_get_runtime_layout_char
    ld (boss_draw_char), a
    call boss_draw_write_cell

.rabte_skip_cell:
    ld a, (boss_restore_col)
    inc a
    ld (boss_restore_col), a
    jp .rabte_col_loop

.rabte_next_row:
    ld a, (boss_restore_row)
    inc a
    ld (boss_restore_row), a
    jp .rabte_row_loop

.rabte_done:
    pop ix
    ret

; Register Contract:
; input: boss_draw_screen_x/boss_draw_screen_y and current boss position/shape
; output: NZ if the current boss has a non-empty tile covering that screen cell, Z otherwise
; clobbers: AF, BC, DE, HL
boss_current_shape_covers_draw_cell:
    ld a, (boss_draw_screen_x)
    ld b, a
    ld a, (boss_x_char)
    cp b
    jp z, .bcscdc_x_in_range
    jp nc, .bcscdc_not_covered
.bcscdc_x_in_range:
    ld a, b
    ld b, a
    ld a, (boss_x_char)
    ld c, a
    ld a, b
    sub c
    ld b, a
    ld a, (boss_width)
    cp b
    jp z, .bcscdc_not_covered
    jp c, .bcscdc_not_covered
    ld a, b
    ld (boss_draw_col), a

    ld a, (boss_draw_screen_y)
    ld b, a
    ld a, (boss_y_char)
    cp b
    jp z, .bcscdc_y_in_range
    jp nc, .bcscdc_not_covered
.bcscdc_y_in_range:
    ld a, b
    ld b, a
    ld a, (boss_y_char)
    ld c, a
    ld a, b
    sub c
    ld b, a
    ld a, (boss_height)
    cp b
    jp z, .bcscdc_not_covered
    jp c, .bcscdc_not_covered
    ld a, b
    ld (boss_draw_row), a

    call boss_get_active_tile_char
    cp #FF
    jp z, .bcscdc_not_covered
    ret
.bcscdc_not_covered:
    xor a
    ret

; Register Contract:
; input: boss_draw_screen_x and boss_draw_screen_y
; output: A = char from runtime_screen_layout at that coordinate
; clobbers: AF, DE, HL
boss_get_runtime_layout_char:
    ld a, (boss_draw_screen_y)
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    add hl, hl
    add hl, hl
    ld a, (boss_draw_screen_x)
    ld e, a
    ld d, 0
    add hl, de
    ld de, runtime_screen_layout
    add hl, de
    ld a, (hl)
    ret

; Register Contract:
; input: boss_draw_row, boss_draw_col, boss_tile_matrix_ptr and boss_width
; output: A = tile char for the current boss cell
; clobbers: AF, B, DE, HL
boss_get_active_tile_char:
    ld a, (boss_draw_row)
    ld b, a
    ld hl, 0
.bgat_row_offset_loop:
    ld a, b
    or a
    jp z, .bgat_row_offset_done
    ld a, (boss_width)
    ld e, a
    ld d, 0
    add hl, de
    dec b
    jp .bgat_row_offset_loop
.bgat_row_offset_done:
    ld a, (boss_draw_col)
    ld e, a
    ld d, 0
    add hl, de
    ld de, (boss_tile_matrix_ptr)
    add hl, de
    ld a, (hl)
    ret

; Register Contract:
; input: boss_draw_screen_x, boss_draw_screen_y and boss_draw_char
; output: one SCREEN 2 name table cell is written
; clobbers: AF, DE, HL
boss_draw_write_cell:
    ld a, (boss_draw_screen_y)
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    add hl, hl
    add hl, hl
    add hl, hl
    ld a, (boss_draw_screen_x)
    ld e, a
    ld d, 0
    add hl, de
    ld de, NAMETBL
    add hl, de
    ld a, (boss_draw_char)
    call FAST_WRTVRM
    ret

; Register Contract:
; input: active boss behavior RAM
; output: boss_x_char/boss_y_char updated according to current behavior action
; clobbers: AF, BC, DE, HL
; preserves: IX
update_boss_behavior:
    push ix
    ld a, (boss_behavior_count)
    or a
    jp z, .ubb_done
    ld a, (boss_behavior_timer)
    or a
    call z, boss_load_current_behavior_action

    ld a, (boss_behavior_action_type)
    cp BOSS_BEHAVIOR_MOVE_TO
    jp z, .ubb_move
    cp BOSS_BEHAVIOR_SLAM
    jp z, .ubb_move
    cp BOSS_BEHAVIOR_ATTACK
    jp z, .ubb_attack
    cp BOSS_BEHAVIOR_SET_FORM
    jp z, .ubb_tick
    cp BOSS_BEHAVIOR_LOOP
    jp z, .ubb_loop
    jp .ubb_tick

.ubb_move:
    call boss_tick_behavior_move_step
    jp z, .ubb_tick
    call boss_step_towards_behavior_target
    jp .ubb_tick

.ubb_attack:
    call boss_draw_behavior_attack
    jp .ubb_tick

.ubb_loop:
    ld a, (boss_behavior_aux0)
    ld b, a
    ld a, (boss_behavior_count)
    cp b
    jp z, .ubb_loop_reset
    jp c, .ubb_loop_reset
    ld a, b
    ld (boss_behavior_index), a
    xor a
    ld (boss_behavior_timer), a
    jp .ubb_done
.ubb_loop_reset:
    xor a
    ld (boss_behavior_index), a
    ld (boss_behavior_timer), a
    jp .ubb_done

.ubb_tick:
    ld a, (boss_behavior_timer)
    or a
    jp z, .ubb_advance
    dec a
    ld (boss_behavior_timer), a
    jp nz, .ubb_done

.ubb_advance:
    ld a, (boss_behavior_index)
    inc a
    ld b, a
    ld a, (boss_behavior_count)
    cp b
    jp nz, .ubb_store_index
    xor a
    jp .ubb_store_index_a
.ubb_store_index:
    ld a, b
.ubb_store_index_a:
    ld (boss_behavior_index), a

.ubb_done:
    pop ix
    ret

; Register Contract:
; input: boss_behavior_table_ptr and boss_behavior_index
; output: current action fields copied to boss_behavior_* RAM
; clobbers: AF, BC, DE, HL
boss_load_current_behavior_action:
    ld hl, (boss_behavior_table_ptr)
    inc hl
    inc hl
    inc hl
    ld a, (boss_behavior_index)
    ld b, a
.blcba_offset_loop:
    ld a, b
    or a
    jp z, .blcba_offset_done
    ld de, BOSS_BEHAVIOR_ACTION_SIZE
    add hl, de
    dec b
    jp .blcba_offset_loop
.blcba_offset_done:
    ld (boss_behavior_action_ptr), hl
    ld a, (hl)
    ld (boss_behavior_action_type), a
    inc hl
    ld a, (hl)
    or a
    jp nz, .blcba_duration_ok
    ld a, 1
.blcba_duration_ok:
    ld (boss_behavior_duration), a
    ld (boss_behavior_timer), a
    inc hl
    ld a, (hl)
    ld (boss_behavior_target_type), a
    inc hl
    ld a, (hl)
    ld (boss_behavior_target_x), a
    inc hl
    ld a, (hl)
    ld (boss_behavior_target_y), a
    inc hl
    ld a, (hl)
    ld (boss_behavior_aux0), a
    inc hl
    ld a, (hl)
    ld (boss_behavior_aux1), a
    inc hl
    ld a, (hl)
    ld (boss_behavior_aux2), a
    ld a, (boss_behavior_action_type)
    cp BOSS_BEHAVIOR_MOVE_TO
    jp z, boss_prepare_behavior_move_timing
    cp BOSS_BEHAVIOR_SLAM
    jp z, boss_prepare_behavior_move_timing
    cp BOSS_BEHAVIOR_SET_FORM
    jp z, boss_apply_behavior_form
    ld a, 1
    ld (boss_behavior_step_interval), a
    ld (boss_behavior_step_timer), a
    ret

; Register Contract:
; input: boss_behavior_aux0 = visual form index, boss_form_table_ptr points to db count + dw form matrices
; output: boss_tile_matrix_ptr switched and boss_visual_dirty set when form index is valid
; clobbers: AF, BC, DE, HL
boss_apply_behavior_form:
    ld hl, (boss_form_table_ptr)
    ld a, h
    cp #FF
    ret z
    ld a, (hl)
    ld b, a
    ld a, (boss_behavior_aux0)
    cp b
    ret nc
    inc hl
    ld b, a
.babf_offset_loop:
    ld a, b
    or a
    jp z, .babf_offset_done
    inc hl
    inc hl
    dec b
    jp .babf_offset_loop
.babf_offset_done:
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld (boss_tile_matrix_ptr), de
    ld a, 1
    ld (boss_visual_dirty), a
    ld (boss_behavior_step_interval), a
    ld (boss_behavior_step_timer), a
    ret

; Register Contract:
; input: freshly loaded move/slam behavior action fields
; output: target resolved once, movement step interval/timer prepared from duration and distance
; clobbers: AF, B, C, D
boss_prepare_behavior_move_timing:
    call boss_resolve_behavior_target
    ld a, (boss_x_char)
    ld b, a
    ld a, (boss_behavior_target_x)
    cp b
    jp nc, .bpbmt_x_positive
    ld a, b
    ld c, a
    ld a, (boss_behavior_target_x)
    ld b, a
    ld a, c
    sub b
    jp .bpbmt_x_ready
.bpbmt_x_positive:
    sub b
.bpbmt_x_ready:
    ld d, a
    ld a, (boss_y_char)
    ld b, a
    ld a, (boss_behavior_target_y)
    cp b
    jp nc, .bpbmt_y_positive
    ld a, b
    ld c, a
    ld a, (boss_behavior_target_y)
    ld b, a
    ld a, c
    sub b
    jp .bpbmt_y_ready
.bpbmt_y_positive:
    sub b
.bpbmt_y_ready:
    cp d
    jp c, .bpbmt_distance_ready
    ld d, a
.bpbmt_distance_ready:
    ld a, d
    or a
    jp nz, .bpbmt_has_distance
    ld a, 1
    ld (boss_behavior_step_interval), a
    ld (boss_behavior_step_timer), a
    ret
.bpbmt_has_distance:
    ld b, a
    ld a, (boss_behavior_duration)
    ld c, 0
.bpbmt_div_loop:
    cp b
    jp c, .bpbmt_div_done
    sub b
    inc c
    jp .bpbmt_div_loop
.bpbmt_div_done:
    ld a, c
    or a
    jp nz, .bpbmt_store_interval
    ld a, 1
.bpbmt_store_interval:
    ld (boss_behavior_step_interval), a
    ld (boss_behavior_step_timer), a
    ret

; Register Contract:
; input: boss_behavior_step_timer/interval
; output: Z flag set when movement should not step; NZ when one tile step should be applied
; clobbers: AF
boss_tick_behavior_move_step:
    ld a, (boss_behavior_step_timer)
    or a
    jp z, .btbms_step
    dec a
    ld (boss_behavior_step_timer), a
    jp nz, .btbms_no_step
.btbms_step:
    ld a, (boss_behavior_step_interval)
    or a
    jp nz, .btbms_has_interval
    ld a, 1
.btbms_has_interval:
    ld (boss_behavior_step_timer), a
    ld a, 1
    or a
    ret
.btbms_no_step:
    xor a
    ret

; Register Contract:
; input: current behavior target fields
; output: boss_behavior_target_x/y resolved for fixed/player/relative targets
; clobbers: AF, B
boss_resolve_behavior_target:
    ld a, (boss_behavior_target_type)
    cp BOSS_BEHAVIOR_TARGET_PLAYER_CURRENT
    jp z, .brbt_player
    cp BOSS_BEHAVIOR_TARGET_PLAYER_PREDICTED
    jp z, .brbt_player
    cp BOSS_BEHAVIOR_TARGET_PLAYER_LAST_KNOWN
    jp z, .brbt_player
    cp BOSS_BEHAVIOR_TARGET_BOSS_RELATIVE
    jp z, .brbt_relative
    ret

.brbt_player:
    ld a, (player_x)
    srl a
    srl a
    srl a
    ld (boss_behavior_target_x), a
    ld a, (player_y)
    srl a
    srl a
    srl a
    ld (boss_behavior_target_y), a
    ret

.brbt_relative:
    ld a, (boss_x_char)
    ld b, a
    ld a, (boss_behavior_target_x)
    add a, b
    ld (boss_behavior_target_x), a
    ld a, (boss_y_char)
    ld b, a
    ld a, (boss_behavior_target_y)
    add a, b
    ld (boss_behavior_target_y), a
    ret

; Register Contract:
; input: boss_x_char/y_char and resolved boss_behavior_target_x/y
; output: boss_x_char/y_char step one char toward target
; clobbers: AF, B
boss_step_towards_behavior_target:
    ld a, (boss_x_char)
    ld b, a
    ld a, (boss_behavior_target_x)
    cp b
    jp z, .bstbt_y
    jp c, .bstbt_dec_x
    ld a, b
    inc a
    ld (boss_x_char), a
    jp .bstbt_y
.bstbt_dec_x:
    ld a, b
    or a
    jp z, .bstbt_y
    dec a
    ld (boss_x_char), a

.bstbt_y:
    ld a, (boss_y_char)
    ld b, a
    ld a, (boss_behavior_target_y)
    cp b
    ret z
    jp c, .bstbt_dec_y
    ld a, b
    inc a
    ld (boss_y_char), a
    ret
.bstbt_dec_y:
    ld a, b
    or a
    ret z
    dec a
    ld (boss_y_char), a
    ret

; Register Contract:
; input: boss_behavior_aux0 = attack index, boss_attack_table_ptr, boss_x/y_char
; output: configured attack renderer invoked at current boss position
; clobbers: AF, BC, DE, HL
boss_draw_behavior_attack:
    ld a, (boss_behavior_aux0)
    cp #FF
    ret z
    ld b, a
    ld hl, (boss_attack_table_ptr)
.bdba_table_loop:
    ld a, b
    or a
    jp z, .bdba_record_ready
    inc hl
    inc hl
    dec b
    jp .bdba_table_loop
.bdba_record_ready:
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld h, d
    ld l, e
    ld a, (boss_x_char)
    add a, a
    add a, a
    add a, a
    ld b, a
    ld a, (boss_y_char)
    add a, a
    add a, a
    add a, a
    ld c, a
    ld d, 24
    ld e, 15
    call draw_boss_attack
    ret

; Register Contract:
; input: A = sprite asset index (#FF = placeholder)
; output: A = hardware sprite base pattern number
; clobbers: AF, BC, HL
boss_attack_get_sprite_pattern:
    cp #FF
    jp z, .bagsp_placeholder
    ld c, a
    ld b, 0
    ld hl, sprite_asset_base_pattern_slot_runtime
    add hl, bc
    ld a, (hl)
    add a, a
    add a, a
    ret
.bagsp_placeholder:
    ld a, (sprite_placeholder_base_pattern_num)
    ret

; Register Contract:
; input: HL = boss attack record
;        B  = base X
;        C  = base Y
;        D  = hardware sprite slot to use
;        E  = sprite color
; output: dispatches to the matching attack renderer
; clobbers: AF plus the selected renderer's documented clobbers
draw_boss_attack:
    ld a, (hl)
    cp BOSS_ATTACK_PROJECTILE
    jp z, draw_boss_projectile_attack
    cp BOSS_ATTACK_METEOR
    jp z, draw_boss_meteor_attack
    cp BOSS_ATTACK_BOMB
    jp z, draw_boss_bomb_attack
    cp BOSS_ATTACK_BOOMERANG
    jp z, draw_boss_boomerang_attack
    cp BOSS_ATTACK_ROCK
    jp z, draw_boss_rock_attack
    cp BOSS_ATTACK_LASER
    jp z, draw_boss_laser_attack
    cp BOSS_ATTACK_SINE_WAVE
    jp z, draw_boss_sine_wave_attack
    cp BOSS_ATTACK_HOMING_MISSILE
    jp z, draw_boss_homing_missile_attack
    cp BOSS_ATTACK_SLAM_ROCKS
    jp z, draw_boss_slam_rocks_attack
    cp BOSS_ATTACK_FALLING_BLOCKS
    jp z, draw_boss_falling_blocks_attack
    ret

; Register Contract:
; input: HL = boss attack record
;        B  = base X
;        C  = base Y
;        D  = hardware sprite slot to use
;        E  = sprite color
; output: starts one simple projectile if none is currently active
; clobbers: AF, BC, DE, HL
; preserves: IX
draw_boss_projectile_attack:
    push ix
    push hl
    pop ix
    ld a, (ix+0)
    cp BOSS_ATTACK_PROJECTILE
    jp nz, .dbpa_done
    ld a, (boss_projectile_active)
    or a
    jp nz, .dbpa_done

    ld a, b
    add a, (ix+5)
    ld (boss_projectile_x), a
    ld a, c
    add a, (ix+6)
    ld (boss_projectile_y), a
    ld a, d
    ld (boss_projectile_sprite_slot), a
    ld a, e
    ld (boss_projectile_color), a

    ld a, (ix+1)
    call boss_attack_get_sprite_pattern
    ld (boss_projectile_pattern), a

    ld a, (ix+3)
    or a
    jp nz, .dbpa_speed_ok
    ld a, 3
.dbpa_speed_ok:
    ld (boss_projectile_speed), a

    ld a, (ix+7)
    or a
    jp nz, .dbpa_range_ok
    ld a, 160
.dbpa_range_ok:
    ld (boss_projectile_range), a

    ld a, (ix+4)
    ld (boss_projectile_direction), a
    xor a
    ld (boss_projectile_distance), a
    ld a, 1
    ld (boss_projectile_active), a
    call boss_projectile_show_current

.dbpa_done:
    pop ix
    ret

; Register Contract:
; input: boss_projectile_* RAM state
; output: active simple boss projectile moved one step or hidden when finished
; clobbers: AF, BC, DE, HL
update_boss_projectile_runtime:
    ld a, (boss_projectile_active)
    or a
    ret z
    ld a, (boss_projectile_distance)
    ld b, a
    ld a, (boss_projectile_speed)
    add a, b
    ld (boss_projectile_distance), a
    ld b, a
    ld a, (boss_projectile_range)
    cp b
    jp c, .ubpr_hide
    jp z, .ubpr_hide

    ld a, (boss_projectile_direction)
    cp BOSS_DIR_RIGHT
    jp z, .ubpr_right
    cp BOSS_DIR_UP
    jp z, .ubpr_up
    cp BOSS_DIR_DOWN
    jp z, .ubpr_down
    ld a, (boss_projectile_x)
    ld b, a
    ld a, (boss_projectile_speed)
    ld h, a
    ld a, b
    sub h
    ld (boss_projectile_x), a
    jp .ubpr_bounds
.ubpr_right:
    ld a, (boss_projectile_x)
    ld b, a
    ld a, (boss_projectile_speed)
    add a, b
    ld (boss_projectile_x), a
    jp .ubpr_bounds
.ubpr_up:
    ld a, (boss_projectile_y)
    ld b, a
    ld a, (boss_projectile_speed)
    ld h, a
    ld a, b
    sub h
    ld (boss_projectile_y), a
    jp .ubpr_bounds
.ubpr_down:
    ld a, (boss_projectile_y)
    ld b, a
    ld a, (boss_projectile_speed)
    add a, b
    ld (boss_projectile_y), a
.ubpr_bounds:
    ld a, (boss_projectile_x)
    cp 248
    jp nc, .ubpr_hide
    ld a, (boss_projectile_y)
    cp 208
    jp nc, .ubpr_hide
    call boss_projectile_show_current
    ret
.ubpr_hide:
    ld a, (boss_projectile_sprite_slot)
    call hide_sprite
    xor a
    ld (boss_projectile_active), a
    ret

; Register Contract:
; input: boss_projectile_* RAM state
; output: projectile sprite attributes written
; clobbers: AF, BC, DE, HL
boss_projectile_show_current:
    ld a, (boss_projectile_x)
    ld b, a
    ld a, (boss_projectile_y)
    ld c, a
    ld a, (boss_projectile_pattern)
    ld d, a
    ld a, (boss_projectile_color)
    ld e, a
    ld a, (boss_projectile_sprite_slot)
    call show_sprite
    ret

; Register Contract:
; input: HL = boss attack record
;        B  = base X
;        C  = base Y
;        D  = first hardware sprite slot to use
;        E  = sprite color
; output: starts one boss rise/slam plus falling-rock sequence if inactive
; clobbers: AF, BC, DE, HL
; preserves: IX
draw_boss_slam_rocks_attack:
    push ix
    push hl
    pop ix
    ld a, (ix+0)
    cp BOSS_ATTACK_SLAM_ROCKS
    jp nz, .dbsr_done
    ld a, (boss_slam_rocks_active)
    or a
    jp nz, .dbsr_done

    ld a, (boss_y_char)
    ld (boss_slam_rocks_origin_y), a
    ld a, d
    ld (boss_slam_rocks_sprite_slot), a
    ld a, e
    ld (boss_slam_rocks_color), a

    ld a, (ix+1)
    call boss_attack_get_sprite_pattern
    ld (boss_slam_rocks_pattern), a

    ld a, (ix+3)
    or a
    jp nz, .dbsr_speed_ok
    ld a, 4
.dbsr_speed_ok:
    ld (boss_slam_rocks_speed), a

    ld a, (ix+7)
    or a
    jp nz, .dbsr_range_ok
    ld a, 216
.dbsr_range_ok:
    ld (boss_slam_rocks_range), a

    ld a, (ix+13)
    or a
    jp nz, .dbsr_count_nonzero
    ld a, 4
.dbsr_count_nonzero:
    cp 5
    jp c, .dbsr_count_ok
    ld a, 4
.dbsr_count_ok:
    ld (boss_slam_rocks_count), a

    ld a, (ix+16)
    or a
    jp nz, .dbsr_duration_ok
    ld a, 80
.dbsr_duration_ok:
    ld (boss_slam_rocks_duration), a

    ld a, (ix+30)
    or a
    jp nz, .dbsr_rise_ok
    ld a, 3
.dbsr_rise_ok:
    ld (boss_slam_rocks_rise_chars), a

    ld a, (ix+31)
    or a
    jp nz, .dbsr_windup_ok
    ld a, 16
.dbsr_windup_ok:
    ld (boss_slam_rocks_windup), a

    ld a, (ix+32)
    or a
    jp nz, .dbsr_slam_ok
    ld a, 6
.dbsr_slam_ok:
    ld (boss_slam_rocks_slam), a

    ld a, (ix+33)
    ld (boss_slam_rocks_hold), a

    ld a, (boss_runtime_tick)
    xor b
    xor c
    ld (boss_slam_rocks_rng), a
    call boss_slam_rocks_seed_lanes
    xor a
    ld (boss_slam_rocks_age), a
    ld a, 1
    ld (boss_slam_rocks_active), a

.dbsr_done:
    pop ix
    ret

; Register Contract:
; input: boss_slam_rocks_* RAM state
; output: boss_y_char and falling rock sprites updated, or sequence hidden when complete
; clobbers: AF, BC, DE, HL
update_boss_slam_rocks_runtime:
    ld a, (boss_slam_rocks_active)
    or a
    ret z
    ld a, (boss_slam_rocks_age)
    inc a
    ld (boss_slam_rocks_age), a
    ld b, a
    ld a, (boss_slam_rocks_duration)
    cp b
    jp c, .ubsr_finish
    jp z, .ubsr_finish

    call boss_slam_rocks_update_boss_y
    call boss_slam_rocks_draw_lanes
    ret
.ubsr_finish:
    ld a, (boss_slam_rocks_origin_y)
    ld (boss_y_char), a
    call boss_slam_rocks_hide_all
    xor a
    ld (boss_slam_rocks_active), a
    ret

; Register Contract:
; input: boss_slam_rocks_age/windup/rise/origin in RAM
; output: boss_y_char raised during windup, restored afterwards
; clobbers: AF, B
boss_slam_rocks_update_boss_y:
    ld a, (boss_slam_rocks_age)
    ld b, a
    ld a, (boss_slam_rocks_windup)
    cp b
    jp c, .bsru_origin
    jp z, .bsru_origin
    ld a, (boss_slam_rocks_origin_y)
    ld b, a
    ld a, (boss_slam_rocks_rise_chars)
    cp b
    jp c, .bsru_subtract
    xor a
    ld (boss_y_char), a
    ret
.bsru_subtract:
    ld a, b
    ld b, a
    ld a, (boss_slam_rocks_rise_chars)
    ld h, a
    ld a, b
    sub h
    ld (boss_y_char), a
    ret
.bsru_origin:
    ld a, (boss_slam_rocks_origin_y)
    ld (boss_y_char), a
    ret

; Register Contract:
; input: none
; output: random X lanes stored for up to four falling rocks
; clobbers: AF, B
boss_slam_rocks_seed_lanes:
    call boss_slam_rocks_random_byte
    call boss_slam_rocks_clamp_random_x
    ld (boss_slam_rock_x0), a
    call boss_slam_rocks_random_byte
    call boss_slam_rocks_clamp_random_x
    ld (boss_slam_rock_x1), a
    call boss_slam_rocks_random_byte
    call boss_slam_rocks_clamp_random_x
    ld (boss_slam_rock_x2), a
    call boss_slam_rocks_random_byte
    call boss_slam_rocks_clamp_random_x
    ld (boss_slam_rock_x3), a
    ret

; Register Contract:
; input: boss_slam_rocks_rng
; output: A = pseudo-random byte
; clobbers: AF, HL
boss_slam_rocks_random_byte:
    ld hl, boss_slam_rocks_rng
    ld a, (hl)
    add a, 37
    xor #A7
    ld (hl), a
    ret

; Register Contract:
; input: A = random byte
; output: A = screen-safe X coordinate for a 16px sprite
; clobbers: AF, B
boss_slam_rocks_clamp_random_x:
    and #F8
    ld b, a
    cp 240
    jp c, .bsrcrx_ok
    ld a, b
    sub 32
.bsrcrx_ok:
    ret

; Register Contract:
; input: boss_slam_rocks_* RAM state
; output: falling rock sprites updated/hidden
; clobbers: AF, BC, DE, HL
boss_slam_rocks_draw_lanes:
    xor a
    ld (boss_slam_rocks_index), a
.bsrdl_loop:
    ld a, (boss_slam_rocks_index)
    ld b, a
    ld a, (boss_slam_rocks_count)
    cp b
    ret z
    ld a, (boss_slam_rocks_index)
    add a, a
    add a, a
    add a, a
    ld b, a
    ld a, (boss_slam_rocks_windup)
    add a, b
    ld b, a
    ld a, (boss_slam_rocks_slam)
    add a, b
    ld b, a
    ld a, (boss_slam_rocks_hold)
    add a, b
    ld b, a                         ; B = lane start age
    ld a, (boss_slam_rocks_age)
    cp b
    jp c, .bsrdl_hide_lane
    sub b
    call boss_slam_rocks_age_to_distance
    ld c, a
    ld a, (boss_slam_rocks_range)
    cp c
    jp c, .bsrdl_hide_lane
    ld b, c                         ; B = Y distance
    call boss_slam_rocks_get_lane_x ; C = X
    ld a, c
    ld b, a                         ; B = X
    ld c, 0
    ld a, (boss_slam_rocks_age)
    ; C already starts at top; B has X. Restore falling Y from saved distance.
    ld a, (boss_slam_rocks_range)
    ; The distance remains in B only until X assignment, so recompute cheaply.
    ld a, (boss_slam_rocks_index)
    add a, a
    add a, a
    add a, a
    ld h, a
    ld a, (boss_slam_rocks_windup)
    add a, h
    ld h, a
    ld a, (boss_slam_rocks_slam)
    add a, h
    ld h, a
    ld a, (boss_slam_rocks_hold)
    add a, h
    ld h, a
    ld a, (boss_slam_rocks_age)
    sub h
    call boss_slam_rocks_age_to_distance
    ld c, a                         ; C = Y
    ld a, (boss_slam_rocks_pattern)
    ld d, a
    ld a, (boss_slam_rocks_color)
    ld e, a
    ld a, (boss_slam_rocks_sprite_slot)
    ld h, a
    ld a, (boss_slam_rocks_index)
    add a, h
    call show_sprite
    jp .bsrdl_next
.bsrdl_hide_lane:
    ld a, (boss_slam_rocks_sprite_slot)
    ld h, a
    ld a, (boss_slam_rocks_index)
    add a, h
    call hide_sprite
.bsrdl_next:
    ld a, (boss_slam_rocks_index)
    inc a
    ld (boss_slam_rocks_index), a
    jp .bsrdl_loop

; Register Contract:
; input: A = fall age in frames
; output: A = age * boss_slam_rocks_speed, 8-bit wrapping
; clobbers: AF, BC, H
boss_slam_rocks_age_to_distance:
    ld b, a
    ld a, (boss_slam_rocks_speed)
