; Register Contract:
; input: B = X, C = Y
; output: sprite_attributes updated for current bomb lane
; clobbers: AF, DE, HL
boss_bomb_show_bomb_lane:
    ld a, (boss_bomb_pattern)
    ld d, a
    ld a, (boss_bomb_color)
    ld e, a
    ld a, (boss_bomb_sprite_slot)
    ld h, a
    ld a, (boss_bomb_index)
