    ld a, e
    ld (boss_boomerang_color), a

    ld a, (ix+1)
    call boss_attack_get_sprite_pattern
    ld (boss_boomerang_pattern), a

    ld a, (ix+3)
    or a
    jp nz, .dboga_speed_ok
    ld a, 3
