; Register Contract:
; input: boss_wave_age/frequency in RAM
; output: boss_wave_phase = floor(age / frequency) & 7
; clobbers: AF, BC, D
boss_wave_compute_phase:
    ld a, (boss_wave_age)
    ld b, a
    ld a, (boss_wave_frequency)
    or a
    jp nz, .bwcp_frequency_ok
    ld a, 4
.bwcp_frequency_ok:
    ld d, a
    ld c, 0
.bwcp_loop:
    ld a, b
    cp d
    jp c, .bwcp_done
    sub d
    ld b, a
    inc c
    jp .bwcp_loop
.bwcp_done:
    ld a, c
    and #07
    ld (boss_wave_phase), a
    ret

; Register Contract:
; input: boss_wave_phase/amplitude in RAM
; output: boss_wave_offset = signed perpendicular sine-like offset
; clobbers: AF, H
boss_wave_compute_offset:
    ld a, (boss_wave_phase)
    and #07
    cp 1
    jp z, .bwco_half_pos
    cp 3
    jp z, .bwco_half_pos
    cp 2
    jp z, .bwco_full_pos
    cp 5
    jp z, .bwco_half_neg
    cp 7
    jp z, .bwco_half_neg
    cp 6
    jp z, .bwco_full_neg
    xor a
    jp .bwco_store
.bwco_half_pos:
    ld a, (boss_wave_amplitude)
    srl a
    jp .bwco_store
.bwco_full_pos:
    ld a, (boss_wave_amplitude)
    jp .bwco_store
.bwco_half_neg:
    ld a, (boss_wave_amplitude)
    srl a
    ld h, a
    xor a
    sub h
    jp .bwco_store
.bwco_full_neg:
    ld a, (boss_wave_amplitude)
    ld h, a
    xor a
    sub h
.bwco_store:
    ld (boss_wave_offset), a
    ret

